#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct RolloutFileIdentity {
    #[cfg(unix)]
    device: u64,
    #[cfg(unix)]
    inode: u64,
    #[cfg(not(unix))]
    is_file: bool,
}

fn rollout_file_identity(metadata: &fs::Metadata) -> RolloutFileIdentity {
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        RolloutFileIdentity {
            device: metadata.dev(),
            inode: metadata.ino(),
        }
    }
    #[cfg(not(unix))]
    {
        RolloutFileIdentity {
            is_file: metadata.is_file(),
        }
    }
}

struct ThreadRolloutCacheEntry {
    identity: RolloutFileIdentity,
    observed_len: u64,
    complete_offset: u64,
    discard_until_lf: bool,
    thread_id: String,
    parser: thread_contract::RolloutAccumulator,
    snapshot: thread_contract::ValidatedRollout,
}

#[derive(Default)]
struct ThreadRolloutCache {
    entries: BTreeMap<PathBuf, ThreadRolloutCacheEntry>,
}

/// Opt-in runtime diagnostics for investigating live update regressions.
///
/// The normal client remains silent and never writes account/session data to
/// logs.  Setting `CODEX_INFO_DEBUG=1` emits only bounded counters and state
/// transitions, which makes a broken worker/update boundary observable without
/// exposing email addresses, URLs, paths, prompts, or token contents.
fn debug_runtime(message: impl AsRef<str>) {
    if std::env::var_os("CODEX_INFO_DEBUG").is_some_and(|value| value == "1") {
        eprintln!("[codex-info] {}", message.as_ref());
    }
}

fn plan_type_label(plan_type: Option<&str>) -> String {
    protocol_contract::plan_label(plan_type)
}

fn monthly_window_seconds(reset_at: i64) -> i64 {
    let Some(end) = DateTime::<Utc>::from_timestamp(reset_at, 0) else {
        return 31 * 86_400;
    };
    end.checked_sub_months(Months::new(1))
        .map(|start| (end - start).num_seconds().max(1))
        .unwrap_or(31 * 86_400)
}

fn parse_rate_limits(
    rate: &Value,
    plan_type: Option<&str>,
    _now: i64,
) -> Result<RateLimitSnapshot, ()> {
    protocol_contract::decode_quota_for_plan(rate, plan_type)
        .map_err(|_| ())?
        .ok_or(())
        .map(|quota| RateLimitSnapshot {
            remaining_percent: quota.remaining_percent.map(f64::from),
            reset_at: quota.reset_at,
            window_seconds: quota.window_seconds,
            limit_name: quota.limit_name,
            quota_title: if quota.monthly {
                "月間残り利用枠".into()
            } else if quota.unlimited {
                "利用枠".into()
            } else {
                "残り利用枠".into()
            },
            monthly: quota.monthly,
        })
}
fn same_rollout_identity(left: &fs::Metadata, right: &fs::Metadata) -> bool {
    use std::os::unix::fs::MetadataExt;

    left.dev() == right.dev() && left.ino() == right.ino()
}

#[cfg(not(unix))]
fn same_rollout_identity(left: &fs::Metadata, right: &fs::Metadata) -> bool {
    left.is_file() && right.is_file()
}

fn complete_rollout_prefix_len(file: &mut File, snapshot_len: u64) -> Result<u64, ()> {
    if snapshot_len == 0 {
        return Ok(0);
    }
    let tail_len = snapshot_len.min(security::MAX_JSONL_LINE_BYTES as u64 + 1);
    let tail_start = snapshot_len.checked_sub(tail_len).ok_or(())?;
    file.seek(SeekFrom::Start(tail_start)).map_err(|_| ())?;
    let capacity = usize::try_from(tail_len).map_err(|_| ())?;
    let mut tail = Vec::with_capacity(capacity);
    file.take(tail_len).read_to_end(&mut tail).map_err(|_| ())?;
    if tail.len() != capacity {
        return Err(());
    }
    if tail.last() == Some(&b'\n') {
        return Ok(snapshot_len);
    }
    if let Some(position) = tail.iter().rposition(|byte| *byte == b'\n') {
        return tail_start
            .checked_add(u64::try_from(position).map_err(|_| ())?)
            .and_then(|position| position.checked_add(1))
            .ok_or(());
    }
    if snapshot_len > security::MAX_JSONL_LINE_BYTES as u64 {
        return Err(());
    }
    Ok(0)
}

fn complete_rollout_range_end(
    file: &mut File,
    start_offset: u64,
    snapshot_len: u64,
) -> Result<u64, ()> {
    if start_offset > snapshot_len {
        return Err(());
    }
    if start_offset == snapshot_len {
        return Ok(snapshot_len);
    }
    file.seek(SeekFrom::Start(start_offset)).map_err(|_| ())?;
    let mut remaining = snapshot_len.checked_sub(start_offset).ok_or(())?;
    let mut offset = start_offset;
    let mut last_newline = None;
    let mut buffer = [0_u8; 64 * 1024];
    while remaining > 0 {
        let limit = usize::try_from(remaining.min(buffer.len() as u64)).map_err(|_| ())?;
        let read = file.read(&mut buffer[..limit]).map_err(|_| ())?;
        if read == 0 {
            return Err(());
        }
        if let Some(index) = buffer[..read].iter().rposition(|byte| *byte == b'\n') {
            let newline_end = offset
                .checked_add(index as u64)
                .and_then(|position| position.checked_add(1))
                .ok_or(())?;
            last_newline = Some(newline_end);
        }
        offset = offset.checked_add(read as u64).ok_or(())?;
        remaining = remaining.checked_sub(read as u64).ok_or(())?;
    }
    if let Some(end) = last_newline {
        return Ok(end);
    }
    if snapshot_len - start_offset > security::MAX_JSONL_LINE_BYTES as u64 {
        return Err(());
    }
    Ok(start_offset)
}

fn first_rollout_newline_end(
    file: &mut File,
    start_offset: u64,
    snapshot_len: u64,
) -> Result<Option<u64>, ()> {
    if start_offset > snapshot_len {
        return Err(());
    }
    if start_offset == snapshot_len {
        return Ok(None);
    }
    file.seek(SeekFrom::Start(start_offset)).map_err(|_| ())?;
    let mut remaining = snapshot_len.checked_sub(start_offset).ok_or(())?;
    let mut offset = start_offset;
    let mut buffer = [0_u8; 64 * 1024];
    while remaining > 0 {
        let limit = usize::try_from(remaining.min(buffer.len() as u64)).map_err(|_| ())?;
        let read = file.read(&mut buffer[..limit]).map_err(|_| ())?;
        if read == 0 {
            return Err(());
        }
        if let Some(index) = buffer[..read].iter().position(|byte| *byte == b'\n') {
            let newline_end = offset
                .checked_add(index as u64)
                .and_then(|position| position.checked_add(1))
                .ok_or(())?;
            if newline_end - start_offset
                > (security::MAX_JSONL_LINE_BYTES as u64).saturating_add(1)
            {
                return Err(());
            }
            return Ok(Some(newline_end));
        }
        offset = offset.checked_add(read as u64).ok_or(())?;
        remaining = remaining.checked_sub(read as u64).ok_or(())?;
        if offset - start_offset > security::MAX_JSONL_LINE_BYTES as u64 {
            return Err(());
        }
    }
    Ok(None)
}

fn rollout_checkpoint_key(
    sessions_root: &Path,
    canonical: &Path,
    file_metadata: &fs::Metadata,
) -> Result<(String, String, u64, u64), ()> {
    let canonical_root = security::validate_absolute_root(sessions_root).map_err(|_| ())?;
    let root_metadata = fs::symlink_metadata(&canonical_root).map_err(|_| ())?;
    if root_metadata.file_type().is_symlink() || !root_metadata.is_dir() {
        return Err(());
    }
    let root_identity = session_root_identity(&canonical_root, &root_metadata).map_err(|_| ())?;
    let relative = canonical.strip_prefix(&canonical_root).map_err(|_| ())?;
    if relative.as_os_str().is_empty()
        || relative
            .components()
            .any(|component| !matches!(component, std::path::Component::Normal(_)))
    {
        return Err(());
    }
    let relative_path = relative.to_str().ok_or(())?.to_owned();
    #[cfg(unix)]
    let (device, inode) = {
        use std::os::unix::fs::MetadataExt;
        (file_metadata.dev(), file_metadata.ino())
    };
    #[cfg(not(unix))]
    let (device, inode) = (0, 0);
    Ok((root_identity, relative_path, device, inode))
}

fn matching_rollout_checkpoint<'a>(
    sessions_root: &Path,
    canonical: &Path,
    file_metadata: &fs::Metadata,
    checkpoints: &'a [usage_store::SessionCheckpoint],
) -> Option<&'a usage_store::SessionCheckpoint> {
    let (root_identity, relative_path, device, inode) =
        rollout_checkpoint_key(sessions_root, canonical, file_metadata).ok()?;
    checkpoints.iter().find(|checkpoint| {
        checkpoint.root_identity == root_identity
            && checkpoint.relative_path == relative_path
            && checkpoint.file_device == device
            && checkpoint.file_inode == inode
    })
}

fn load_thread_rollout_checkpoints(
    partition: &account_scope::AccountPartition,
) -> Vec<usage_store::SessionCheckpoint> {
    match fs::symlink_metadata(&partition.database_path) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_file() => {
            return Vec::new()
        }
        Ok(_) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Vec::new(),
        Err(_) => return Vec::new(),
    }
    let identity = partition.storage_identity();
    UsageStore::open_read_only_partitioned(&partition.database_path, &identity)
        .and_then(|store| store.load_session_collection_state())
        .map(|state| state.checkpoints)
        .unwrap_or_default()
}

fn read_thread_session_meta_id(file: &mut File) -> Result<String, ()> {
    file.seek(SeekFrom::Start(0)).map_err(|_| ())?;
    let max_record_bytes = security::MAX_JSONL_LINE_BYTES.checked_add(1).ok_or(())?;
    let mut reader = BufReader::new((&mut *file).take(max_record_bytes as u64));
    let Some((line, true)) = security::read_bounded_jsonl_record(&mut reader).map_err(|_| ())?
    else {
        return Err(());
    };
    let value: Value = serde_json::from_str(&line).map_err(|_| ())?;
    let object = value.as_object().ok_or(())?;
    if object.get("type").and_then(Value::as_str) != Some("session_meta") {
        return Err(());
    }
    object
        .get("payload")
        .and_then(Value::as_object)
        .and_then(|payload| payload.get("id"))
        .and_then(Value::as_str)
        .filter(|id| {
            let length = id.chars().count();
            (1..=128).contains(&length) && !id.chars().any(char::is_control)
        })
        .map(ToOwned::to_owned)
        .ok_or(())
}

#[cfg(test)]
fn read_thread_rollout_path(
    sessions_root: &Path,
    candidate_path: &Path,
) -> Result<thread_contract::ValidatedRollout, ()> {
    read_thread_rollout_snapshot(sessions_root, candidate_path, false).map(|(_, rollout)| rollout)
}

#[cfg(test)]
fn read_thread_rollout_snapshot(
    sessions_root: &Path,
    candidate_path: &Path,
    require_thread_id: bool,
) -> Result<(Option<String>, thread_contract::ValidatedRollout), ()> {
    let canonical =
        security::canonical_regular_file_under(sessions_root, candidate_path).map_err(|_| ())?;
    let before_path = fs::symlink_metadata(&canonical).map_err(|_| ())?;
    if before_path.file_type().is_symlink() || !before_path.is_file() {
        return Err(());
    }
    let mut file = File::open(&canonical).map_err(|_| ())?;
    let before_file = file.metadata().map_err(|_| ())?;
    if !same_rollout_identity(&before_path, &before_file) {
        return Err(());
    }
    let snapshot_len = before_file.len();
    let complete_len = complete_rollout_prefix_len(&mut file, snapshot_len)?;
    let thread_id = if require_thread_id {
        file.seek(SeekFrom::Start(0)).map_err(|_| ())?;
        let mut reader = BufReader::new((&mut file).take(complete_len));
        let Some((line, true)) =
            security::read_bounded_jsonl_record(&mut reader).map_err(|_| ())?
        else {
            return Err(());
        };
        let value: Value = serde_json::from_str(&line).map_err(|_| ())?;
        let object = value.as_object().ok_or(())?;
        if object.get("type").and_then(Value::as_str) != Some("session_meta") {
            return Err(());
        }
        let id = object
            .get("payload")
            .and_then(Value::as_object)
            .and_then(|payload| payload.get("id"))
            .and_then(Value::as_str)
            .filter(|id| {
                let length = id.chars().count();
                (1..=128).contains(&length) && !id.chars().any(char::is_control)
            })
            .ok_or(())?;
        Some(id.to_owned())
    } else {
        None
    };
    file.seek(SeekFrom::Start(0)).map_err(|_| ())?;
    let rollout = {
        let mut reader = BufReader::new((&mut file).take(complete_len));
        match thread_contract::parse_rollout_reader_recoverable(&mut reader, complete_len) {
            Ok(rollout) => rollout,
            Err(error) => {
                debug_runtime(format!(
                    "thread rollout parse rejected reason={}",
                    error.message()
                ));
                return Err(());
            }
        }
    };

    let after_file = file.metadata().map_err(|_| ())?;
    let after_path = fs::symlink_metadata(&canonical).map_err(|_| ())?;
    if after_path.file_type().is_symlink()
        || !after_path.is_file()
        || !same_rollout_identity(&before_file, &after_file)
        || !same_rollout_identity(&after_file, &after_path)
        || after_file.len() < snapshot_len
    {
        return Err(());
    }
    Ok((thread_id, rollout))
}

/// Read an active rollout through the worker-owned append-only cache.
///
/// The cache key is the canonical path and the entry's identity.  A matching
/// entry only consumes complete records after its prior complete offset.  A
/// partial tail is deliberately left at that offset so a later append can
/// complete and validate the same record. Identity changes and truncation
/// discard the entry and use a matching durable seed or bounded bootstrap.
#[cfg(test)]
fn read_active_thread_rollout_cached(
    sessions_root: &Path,
    candidate_path: &Path,
    cache: &mut ThreadRolloutCache,
) -> Result<(String, thread_contract::ValidatedRollout), ()> {
    read_active_thread_rollout_cached_with_checkpoints(sessions_root, candidate_path, cache, &[])
}

fn read_active_thread_rollout_cached_with_checkpoints(
    sessions_root: &Path,
    candidate_path: &Path,
    cache: &mut ThreadRolloutCache,
    checkpoints: &[usage_store::SessionCheckpoint],
) -> Result<(String, thread_contract::ValidatedRollout), ()> {
    let canonical =
        security::canonical_regular_file_under(sessions_root, candidate_path).map_err(|_| ())?;
    let before_path = fs::symlink_metadata(&canonical).map_err(|_| ())?;
    if before_path.file_type().is_symlink() || !before_path.is_file() {
        return Err(());
    }
    let mut file = File::open(&canonical).map_err(|_| ())?;
    let before_file = file.metadata().map_err(|_| ())?;
    if !same_rollout_identity(&before_path, &before_file) {
        return Err(());
    }
    let snapshot_len = before_file.len();
    let identity = rollout_file_identity(&before_file);
    let cached_entry = cache.entries.get(&canonical);
    let (reusable, parse_start, complete_len, discard_until_lf) = match cached_entry {
        Some(entry)
            if entry.identity == identity
                && entry.complete_offset <= entry.observed_len
                && snapshot_len == entry.observed_len =>
        {
            // An unchanged snapshot is already represented by the cached
            // parser/snapshot.  Do not inspect even the file tail.
            (
                true,
                entry.complete_offset,
                entry.complete_offset,
                entry.discard_until_lf,
            )
        }
        Some(entry)
            if entry.identity == identity
                && entry.complete_offset <= entry.observed_len
                && snapshot_len > entry.observed_len =>
        {
            if entry.discard_until_lf {
                match first_rollout_newline_end(&mut file, entry.complete_offset, snapshot_len)? {
                    Some(start) => (
                        true,
                        start,
                        complete_rollout_range_end(&mut file, start, snapshot_len)?,
                        false,
                    ),
                    None => (true, entry.complete_offset, entry.complete_offset, true),
                }
            } else {
                (
                    true,
                    entry.complete_offset,
                    complete_rollout_range_end(&mut file, entry.complete_offset, snapshot_len)?,
                    false,
                )
            }
        }
        _ => {
            let checkpoint =
                matching_rollout_checkpoint(sessions_root, &canonical, &before_file, checkpoints);
            match checkpoint {
                Some(checkpoint) => {
                    if checkpoint.committed_offset > snapshot_len {
                        return Err(());
                    }
                    if checkpoint.discard_until_lf {
                        match first_rollout_newline_end(
                            &mut file,
                            checkpoint.committed_offset,
                            snapshot_len,
                        )? {
                            Some(start) => (
                                false,
                                start,
                                complete_rollout_range_end(&mut file, start, snapshot_len)?,
                                false,
                            ),
                            None => (
                                false,
                                checkpoint.committed_offset,
                                checkpoint.committed_offset,
                                true,
                            ),
                        }
                    } else {
                        (
                            false,
                            checkpoint.committed_offset,
                            complete_rollout_range_end(
                                &mut file,
                                checkpoint.committed_offset,
                                snapshot_len,
                            )?,
                            false,
                        )
                    }
                }
                None => {
                    if snapshot_len > security::MAX_JSONL_LINE_BYTES as u64 {
                        return Err(());
                    }
                    let complete_len = complete_rollout_prefix_len(&mut file, snapshot_len)?;
                    (false, 0, complete_len, false)
                }
            }
        }
    };
    let (thread_id, parser, complete_offset, snapshot) = if reusable {
        let entry = cache.entries.get(&canonical).ok_or(())?;
        let mut parser = entry.parser.clone();
        if complete_len > parse_start {
            let appended_len = complete_len.checked_sub(parse_start).ok_or(())?;
            file.seek(SeekFrom::Start(parse_start)).map_err(|_| ())?;
            let mut reader = BufReader::new((&mut file).take(appended_len));
            parser
                .apply_reader(&mut reader, appended_len)
                .map_err(|_| ())?;
        }
        let snapshot = if complete_len > parse_start {
            parser.snapshot().map_err(|_| ())?
        } else {
            entry.snapshot.clone()
        };
        (entry.thread_id.clone(), parser, complete_len, snapshot)
    } else {
        let checkpoint =
            matching_rollout_checkpoint(sessions_root, &canonical, &before_file, checkpoints);
        let mut parser = checkpoint
            .map(|checkpoint| {
                thread_contract::RolloutAccumulator::seeded(
                    checkpoint.last_model.clone(),
                    checkpoint.previous_total,
                    checkpoint
                        .last_task_running
                        .or_else(|| (complete_len > parse_start).then_some(true)),
                )
            })
            .unwrap_or_else(thread_contract::RolloutAccumulator::new);
        let thread_id = read_thread_session_meta_id(&mut file)?;
        if complete_len > parse_start {
            let appended_len = complete_len.checked_sub(parse_start).ok_or(())?;
            file.seek(SeekFrom::Start(parse_start)).map_err(|_| ())?;
            let mut reader = BufReader::new((&mut file).take(appended_len));
            parser
                .apply_reader(&mut reader, appended_len)
                .map_err(|_| ())?;
        }
        let snapshot = parser.snapshot().map_err(|_| ())?;
        (thread_id, parser, complete_len, snapshot)
    };

    let after_file = file.metadata().map_err(|_| ())?;
    let after_path = fs::symlink_metadata(&canonical).map_err(|_| ())?;
    if after_path.file_type().is_symlink()
        || !after_path.is_file()
        || !same_rollout_identity(&before_file, &after_file)
        || !same_rollout_identity(&after_file, &after_path)
        || after_file.len() < snapshot_len
    {
        return Err(());
    }

    cache.entries.insert(
        canonical,
        ThreadRolloutCacheEntry {
            identity,
            observed_len: snapshot_len,
            complete_offset,
            discard_until_lf,
            thread_id: thread_id.clone(),
            parser,
            snapshot: snapshot.clone(),
        },
    );
    Ok((thread_id, snapshot))
}

const MAX_PROC_PROCESS_ENTRIES: usize = 65_536;
const MAX_CODEX_PROCESS_FDS: usize = 16_384;
const MAX_OPEN_SESSION_FILES: usize = 1_024;

fn proc_value_or_disappeared<T>(result: std::io::Result<T>) -> Result<Option<T>, ()> {
    match result {
        Ok(value) => Ok(Some(value)),
        // Processes and descriptors can disappear between two `/proc` reads.
        // Once gone they cannot keep a session file open. Every other error
        // makes the active-file inventory incomplete and rejects the batch.
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(_) => Err(()),
    }
}

fn open_codex_session_paths(
    proc_root: &Path,
    sessions_root: &Path,
) -> Result<BTreeSet<PathBuf>, ()> {
    let mut process_entries = 0usize;
    let mut open_files = BTreeSet::new();
    for process in fs::read_dir(proc_root).map_err(|_| ())? {
        process_entries = process_entries.checked_add(1).ok_or(())?;
        if process_entries > MAX_PROC_PROCESS_ENTRIES {
            return Err(());
        }
        let Some(process) = proc_value_or_disappeared(process)? else {
            continue;
        };
        let name = process.file_name();
        let Some(name) = name.to_str() else {
            continue;
        };
        if name.is_empty() || !name.bytes().all(|byte| byte.is_ascii_digit()) {
            continue;
        }
        let process_path = process.path();
        let Some(file) = proc_value_or_disappeared(File::open(process_path.join("comm")))? else {
            continue;
        };
        let mut comm = Vec::new();
        file.take(64).read_to_end(&mut comm).map_err(|_| ())?;
        if comm.strip_suffix(b"\n") != Some(b"codex") && comm.as_slice() != b"codex" {
            continue;
        }
        let Some(executable) = proc_value_or_disappeared(fs::read_link(process_path.join("exe")))?
        else {
            continue;
        };
        if executable.file_name().and_then(|name| name.to_str()) != Some("codex") {
            continue;
        }
        let Some(descriptors) = proc_value_or_disappeared(fs::read_dir(process_path.join("fd")))?
        else {
            continue;
        };
        let mut descriptor_count = 0usize;
        for descriptor in descriptors {
            descriptor_count = descriptor_count.checked_add(1).ok_or(())?;
            if descriptor_count > MAX_CODEX_PROCESS_FDS {
                return Err(());
            }
            let Some(descriptor) = proc_value_or_disappeared(descriptor)? else {
                continue;
            };
            let Some(target) = proc_value_or_disappeared(fs::read_link(descriptor.path()))? else {
                continue;
            };
            let Ok(canonical) = security::canonical_regular_file_under(sessions_root, &target)
            else {
                continue;
            };
            if canonical
                .extension()
                .and_then(|extension| extension.to_str())
                != Some("jsonl")
            {
                continue;
            }
            open_files.insert(canonical);
            if open_files.len() > MAX_OPEN_SESSION_FILES {
                return Err(());
            }
        }
    }
    Ok(open_files)
}

fn active_thread_paths(codex_root: &Path) -> Result<(PathBuf, BTreeSet<PathBuf>), ()> {
    let sessions_root = codex_root.join("sessions");
    let active_paths = open_codex_session_paths(Path::new("/proc"), &sessions_root)?;
    debug_runtime(format!("thread active paths={}", active_paths.len()));
    Ok((sessions_root, active_paths))
}

#[derive(Debug, Default, Eq, PartialEq)]
struct SessionCleanupReport {
    deleted: Vec<usage_store::RecordedSessionSource>,
    retained: usize,
    database_failed: bool,
    process_scan_failed: bool,
}

fn current_session_candidate(
    sessions_root: &Path,
    expected_path: &Path,
) -> Result<(PathBuf, usage_store::RecordedSessionSource), security::SecurityError> {
    let canonical_root = security::validate_absolute_root(sessions_root)?;
    let root_metadata = fs::symlink_metadata(&canonical_root)
        .map_err(|_| security::SecurityError::new(security::SecurityErrorKind::UnsafePath))?;
    let root_identity = session_root_identity(&canonical_root, &root_metadata)?;
    let canonical = security::canonical_regular_file_under(&canonical_root, expected_path)?;
    if canonical != expected_path {
        return Err(security::SecurityError::new(
            security::SecurityErrorKind::UnsafePath,
        ));
    }
    let metadata = fs::symlink_metadata(&canonical)
        .map_err(|_| security::SecurityError::new(security::SecurityErrorKind::UnsafePath))?;
    let fingerprint = local_input_file_fingerprint(&canonical, &metadata)?;
    let source = recorded_session_source(&canonical_root, &root_identity, &fingerprint)?;
    Ok((canonical, source))
}

fn cleanup_recorded_session_overflow_partitioned_with<F>(
    database: &Path,
    partition_identity: Option<&StoragePartitionIdentity>,
    plan: &SessionCleanupPlan,
    active_paths: Result<BTreeSet<PathBuf>, ()>,
    mut remove_file: F,
) -> SessionCleanupReport
where
    F: FnMut(&Path) -> std::io::Result<()>,
{
    let mut report = SessionCleanupReport::default();
    let active_paths = match active_paths {
        Ok(paths) => paths,
        Err(()) => {
            report.retained = plan.overflow_files.len();
            report.process_scan_failed = true;
            return report;
        }
    };
    let store = match partition_identity {
        Some(identity) => UsageStore::open_read_only_partitioned(database, identity),
        #[cfg(test)]
        None => UsageStore::open_read_only(database),
        #[cfg(not(test))]
        None => Err(usage_store::UsageStoreError::InvalidImport(
            "cleanup partition identity is missing".into(),
        )),
    };
    let store = match store {
        Ok(store) => store,
        Err(_) => {
            report.retained = plan.overflow_files.len();
            report.database_failed = true;
            return report;
        }
    };

    // Complete every durable-marker read before unlinking anything. A schema
    // or SQLite read failure therefore keeps the entire cleanup batch.
    let mut authorized = Vec::new();
    for candidate in &plan.overflow_files {
        if plan.selected_paths.contains(&candidate.fingerprint.path) {
            report.retained = report.retained.saturating_add(1);
            continue;
        }
        match store.recorded_session_matches(&candidate.recorded_source) {
            Ok(true) => authorized.push(candidate),
            Ok(false) => report.retained = report.retained.saturating_add(1),
            Err(_) => {
                report.retained = plan.overflow_files.len();
                report.database_failed = true;
                return report;
            }
        }
    }

    for candidate in authorized {
        let Ok((canonical, current)) =
            current_session_candidate(&plan.sessions_root, &candidate.fingerprint.path)
        else {
            report.retained = report.retained.saturating_add(1);
            continue;
        };
        if current != candidate.recorded_source || active_paths.contains(&canonical) {
            report.retained = report.retained.saturating_add(1);
            continue;
        }
        let Ok((before_remove, current)) =
            current_session_candidate(&plan.sessions_root, &candidate.fingerprint.path)
        else {
            report.retained = report.retained.saturating_add(1);
            continue;
        };
        if before_remove != canonical || current != candidate.recorded_source {
            report.retained = report.retained.saturating_add(1);
            continue;
        }
        if remove_file(&canonical).is_err() {
            report.retained = report.retained.saturating_add(1);
            continue;
        }
        report.deleted.push(candidate.recorded_source.clone());
    }
    report
}

#[cfg(test)]
fn cleanup_recorded_session_overflow_with<F>(
    database: &Path,
    plan: &SessionCleanupPlan,
    active_paths: Result<BTreeSet<PathBuf>, ()>,
    remove_file: F,
) -> SessionCleanupReport
where
    F: FnMut(&Path) -> std::io::Result<()>,
{
    cleanup_recorded_session_overflow_partitioned_with(
        database,
        None,
        plan,
        active_paths,
        remove_file,
    )
}

fn cleanup_recorded_session_overflow_partitioned(
    database: &Path,
    partition_identity: &StoragePartitionIdentity,
    plan: &SessionCleanupPlan,
    proc_root: &Path,
) -> SessionCleanupReport {
    let active_paths = open_codex_session_paths(proc_root, &plan.sessions_root);
    cleanup_recorded_session_overflow_partitioned_with(
        database,
        Some(partition_identity),
        plan,
        active_paths,
        |path| fs::remove_file(path),
    )
}

#[cfg(test)]
fn cleanup_recorded_session_overflow(
    database: &Path,
    plan: &SessionCleanupPlan,
    proc_root: &Path,
) -> SessionCleanupReport {
    let active_paths = open_codex_session_paths(proc_root, &plan.sessions_root);
    cleanup_recorded_session_overflow_partitioned_with(database, None, plan, active_paths, |path| {
        fs::remove_file(path)
    })
}

fn fetch_active_thread_update(
    input: &mut impl Write,
    output: &Receiver<RpcReadEvent>,
    next_id: &mut u64,
    sessions_root: &Path,
    active_paths: &BTreeSet<PathBuf>,
    deadline: Instant,
    rollout_cache: &mut ThreadRolloutCache,
    checkpoints: &[usage_store::SessionCheckpoint],
) -> ActiveThreadUpdate {
    fetch_active_thread_update_before_deadline_with_cache(
        input,
        output,
        next_id,
        sessions_root,
        active_paths,
        deadline,
        rollout_cache,
        checkpoints,
    )
}

#[cfg(test)]
fn fetch_active_thread_update_for_paths(
    input: &mut impl Write,
    output: &Receiver<RpcReadEvent>,
    next_id: &mut u64,
    sessions_root: &Path,
    active_paths: &BTreeSet<PathBuf>,
) -> ActiveThreadUpdate {
    fetch_active_thread_update_for_paths_and_state(
        input,
        output,
        next_id,
        sessions_root,
        active_paths,
        None,
    )
}

#[cfg(test)]
fn fetch_active_thread_update_for_paths_and_state(
    input: &mut impl Write,
    output: &Receiver<RpcReadEvent>,
    next_id: &mut u64,
    sessions_root: &Path,
    active_paths: &BTreeSet<PathBuf>,
    _codex_root: Option<&Path>,
) -> ActiveThreadUpdate {
    let mut rollout_cache = ThreadRolloutCache::default();
    fetch_active_thread_update_before_deadline_with_cache(
        input,
        output,
        next_id,
        sessions_root,
        active_paths,
        Instant::now() + security::RPC_RESPONSE_TIMEOUT,
        &mut rollout_cache,
        &[],
    )
}

fn fetch_active_thread_update_before_deadline_with_cache(
    input: &mut impl Write,
    output: &Receiver<RpcReadEvent>,
    next_id: &mut u64,
    sessions_root: &Path,
    active_paths: &BTreeSet<PathBuf>,
    deadline: Instant,
    rollout_cache: &mut ThreadRolloutCache,
    checkpoints: &[usage_store::SessionCheckpoint],
) -> ActiveThreadUpdate {
    rollout_cache
        .entries
        .retain(|path, _| active_paths.contains(path));
    let mut rollouts = BTreeMap::new();
    let mut thread_items = Vec::with_capacity(active_paths.len());
    for active_path in active_paths {
        let (thread_id, rollout) = match read_active_thread_rollout_cached_with_checkpoints(
            sessions_root,
            active_path,
            rollout_cache,
            checkpoints,
        ) {
            Ok(value) => value,
            Err(()) => {
                debug_runtime("thread active rollout identity rejected");
                return ActiveThreadUpdate::Failed;
            }
        };
        let request_id = *next_id;
        let Some(following_id) = next_id.checked_add(1) else {
            return ActiveThreadUpdate::Failed;
        };
        *next_id = following_id;
        let Some(wait) = deadline.checked_duration_since(Instant::now()) else {
            debug_runtime("thread read cycle timed out");
            return ActiveThreadUpdate::Failed;
        };
        let result = match request_with_timeout_observed(
            input,
            output,
            request_id,
            "thread/read",
            json!({"threadId": thread_id, "includeTurns": false}),
            wait,
            None,
        ) {
            Ok(result) => result,
            Err(_) => {
                debug_runtime("thread read RPC failed");
                return ActiveThreadUpdate::Failed;
            }
        };
        let Some(result_object) = result.as_object().filter(|object| object.len() == 1) else {
            debug_runtime("thread read response envelope rejected");
            return ActiveThreadUpdate::Failed;
        };
        let Some(thread_item) = result_object.get("thread") else {
            debug_runtime("thread read response missing thread");
            return ActiveThreadUpdate::Failed;
        };
        let candidate = match thread_contract::validate_thread_item(thread_item) {
            Ok(candidate) => candidate,
            Err(_) => {
                debug_runtime("thread read response rejected");
                return ActiveThreadUpdate::Failed;
            }
        };
        let response_path = candidate.path().and_then(|path| {
            security::canonical_regular_file_under(sessions_root, Path::new(path)).ok()
        });
        if candidate.id() != thread_id || response_path.as_ref() != Some(active_path) {
            debug_runtime("thread read identity mismatch");
            return ActiveThreadUpdate::Failed;
        }
        if rollouts.insert(thread_id, rollout).is_some() {
            debug_runtime("thread read duplicate identity");
            return ActiveThreadUpdate::Failed;
        }
        thread_items.push(thread_item.clone());
    }

    let mut accumulator = ThreadCycleAccumulator::new();
    if accumulator
        .accept_page(&json!({"data": thread_items}))
        .is_err()
    {
        debug_runtime("thread read cycle rejected");
        return ActiveThreadUpdate::Failed;
    }

    let root_outcome = thread_contract::select_active_threads_parsed_where(
        accumulator,
        |candidate| {
            candidate
                .path()
                .and_then(|path| {
                    security::canonical_regular_file_under(sessions_root, Path::new(path)).ok()
                })
                .is_some_and(|path| active_paths.contains(&path))
        },
        |candidate| rollouts.get(candidate.id()).cloned().ok_or(()),
    );
    let root_snapshots = match root_outcome {
        ThreadCycleOutcome::Snapshots(snapshots) => snapshots,
        ThreadCycleOutcome::NoThread => Vec::new(),
        ThreadCycleOutcome::CycleError => {
            debug_runtime("thread active candidate selection failed");
            return ActiveThreadUpdate::Failed;
        }
    };
    debug_runtime(format!("thread active snapshots={}", root_snapshots.len()));

    let mut threads = root_snapshots
        .into_iter()
        .map(|snapshot| ActiveThread {
            id: snapshot.thread_id,
            created_at: Some(snapshot.created_at),
            updated_at: snapshot.updated_at,
            title: snapshot.title,
            model: snapshot.model,
            model_label: snapshot.model_label,
            total_tokens: snapshot.total_tokens,
            context_usage_tokens: snapshot.context_usage_tokens,
            context_window_tokens: snapshot.context_window_tokens,
            last_user_message_at: snapshot.last_user_message_at,
            is_subagent: snapshot.is_subagent,
            parent_thread_id: snapshot.parent_thread_id,
            depth: snapshot.depth,
        })
        .collect::<Vec<_>>();

    threads.sort_by(|left, right| {
        right
            .updated_at
            .cmp(&left.updated_at)
            .then_with(|| right.id.cmp(&left.id))
    });
    if threads.is_empty() {
        ActiveThreadUpdate::NoThread
    } else {
        ActiveThreadUpdate::Snapshot(threads)
    }
}

#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
struct UsageHistorySample {
    timestamp: i64,
    reset_at: i64,
    remaining_percent: f64,
    sol_dollars: f64,
    terra_dollars: f64,
    luna_dollars: f64,
    #[serde(default)]
    sol_tokens: u64,
    #[serde(default)]
    terra_tokens: u64,
    #[serde(default)]
    luna_tokens: u64,
}

impl UsageHistorySample {
    fn from_store(sample: usage_store::UsageHistorySample) -> Self {
        Self {
            timestamp: sample.timestamp,
            reset_at: sample.reset_at,
            remaining_percent: sample.remaining_percent.unwrap_or(-1.0),
            sol_dollars: sample.sol_dollars,
            terra_dollars: sample.terra_dollars,
            luna_dollars: sample.luna_dollars,
            sol_tokens: sample.sol_tokens,
            terra_tokens: sample.terra_tokens,
            luna_tokens: sample.luna_tokens,
        }
    }

    fn to_store(&self) -> usage_store::UsageHistorySample {
        usage_store::UsageHistorySample {
            timestamp: self.timestamp,
            reset_at: self.reset_at,
            remaining_percent: (self.remaining_percent >= 0.0).then_some(self.remaining_percent),
            sol_dollars: self.sol_dollars,
            terra_dollars: self.terra_dollars,
            luna_dollars: self.luna_dollars,
            sol_tokens: self.sol_tokens,
            terra_tokens: self.terra_tokens,
            luna_tokens: self.luna_tokens,
        }
    }

    #[cfg(test)]
    fn new(
        timestamp: i64,
        reset_at: i64,
        remaining_percent: f64,
        costs: ModelDollarTotals,
    ) -> Self {
        Self::new_with_usage(
            timestamp,
            reset_at,
            remaining_percent,
            costs,
            ModelTokenTotals::default(),
        )
    }

    fn new_with_usage(
        timestamp: i64,
        reset_at: i64,
        remaining_percent: f64,
        costs: ModelDollarTotals,
        tokens: ModelTokenTotals,
    ) -> Self {
        Self {
            // 1分ごとの取得値として、同じ分に複数回届いた場合も1点にまとめる。
            timestamp: timestamp.div_euclid(60) * 60,
            reset_at,
            remaining_percent: remaining_percent.clamp(0.0, 100.0),
            sol_dollars: costs.sol.max(0.0),
            terra_dollars: costs.terra.max(0.0),
            luna_dollars: costs.luna.max(0.0),
            sol_tokens: tokens.sol,
            terra_tokens: tokens.terra,
            luna_tokens: tokens.luna,
        }
    }

    #[cfg(test)]
    fn from_model_history(timestamp: i64, reset_at: i64, costs: ModelDollarTotals) -> Self {
        Self::from_model_history_with_usage(timestamp, reset_at, costs, ModelTokenTotals::default())
    }

    fn from_model_history_with_usage(
        timestamp: i64,
        reset_at: i64,
        costs: ModelDollarTotals,
        tokens: ModelTokenTotals,
    ) -> Self {
        Self {
            timestamp: timestamp.div_euclid(60) * 60,
            reset_at,
            // セッションログには残り利用枠の履歴がないため、グラフでは欠測として扱う。
            remaining_percent: -1.0,
            sol_dollars: costs.sol.max(0.0),
            terra_dollars: costs.terra.max(0.0),
            luna_dollars: costs.luna.max(0.0),
            sol_tokens: tokens.sol,
            terra_tokens: tokens.terra,
            luna_tokens: tokens.luna,
        }
    }

    fn is_valid(&self) -> bool {
        self.timestamp > 0
            && self.reset_at > 0
            && self.remaining_percent.is_finite()
            && self.sol_dollars.is_finite()
            && self.terra_dollars.is_finite()
            && self.luna_dollars.is_finite()
    }
}

fn same_reset_period(left: i64, right: i64) -> bool {
    left.abs_diff(right) <= RESET_AT_TOLERANCE_SECONDS as u64
}

/// Decide whether a newly reported reset timestamp is a real period boundary
/// or merely the service's rolling `now + window` value moving between polls.
/// The latter is common in the live response and must never make the main
/// screen throw away a complete model/history snapshot.
fn reset_transition_is_boundary(
    previous_reset: Option<i64>,
    previous_remaining: Option<f64>,
    next_reset: i64,
    next_remaining: Option<f64>,
    previous_observed_at: Option<i64>,
    now: i64,
    window_seconds: i64,
) -> bool {
    let Some(previous_reset) = previous_reset else {
        return next_reset > 0;
    };
    if next_reset <= 0 || same_reset_period(previous_reset, next_reset) {
        return false;
    }

    // A real reset is accompanied by a material quota refill.  A one-point
    // rounding fluctuation is not enough to change period identity.
    if let (Some(previous), Some(next)) = (previous_remaining, next_remaining) {
        if next.is_finite() && previous.is_finite() && next >= previous + 5.0 {
            return true;
        }
    }

    // If the prior observation was close to its boundary and the new one is
    // a full window ahead, this is a genuine rollover even when the quota
    // percentage is unavailable. Otherwise, two full-window horizons are the
    // same rolling period regardless of their absolute reset timestamps.
    let previous_at = previous_observed_at.unwrap_or(now);
    let previous_horizon = previous_reset.saturating_sub(previous_at);
    let next_horizon = next_reset.saturating_sub(now);
    let boundary_proximity = window_seconds.clamp(60, 3_600);
    if previous_horizon <= boundary_proximity && next_horizon >= window_seconds / 2 {
        return true;
    }
    false
}

/// Admit the durable absolute model totals for the next collector cycle.
/// Reset timestamps are observations, not period identifiers: rolling drift
/// and daemon downtime retain the baseline, while a verified rollover or a
/// changed quota window starts the next cumulative period at zero. Session
/// checkpoints deliberately survive both paths because token records remain
/// append-only across quota periods.
fn admit_session_collection_period(
    state: &mut usage_store::SessionCollectionState,
    next_reset_at: i64,
    next_window_seconds: i64,
    next_remaining_percent: Option<f64>,
    now: i64,
) -> bool {
    if state.data_generation == 0 {
        return false;
    }
    let observation = state.last_quota_observation.as_ref();
    let boundary = state.window_seconds != next_window_seconds
        || reset_transition_is_boundary(
            (state.reset_at > 0).then_some(state.reset_at),
            observation.map(|value| value.remaining_percent),
            next_reset_at,
            next_remaining_percent,
            observation.map(|value| value.observed_at),
            now,
            state.window_seconds,
        );
    if boundary {
        state.model_totals.clear();
    }
    boundary
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct HistoryPeriod {
    canonical_reset_at: i64,
    start: i64,
    end: i64,
    label: String,
}

fn display_history_samples(samples: &[UsageHistorySample]) -> Vec<&UsageHistorySample> {
    samples.iter().filter(|sample| sample.is_valid()).collect()
}

#[derive(Clone, Debug)]
struct ResetSampleGroup {
    canonical_reset_at: i64,
    start: i64,
    samples: Vec<UsageHistorySample>,
}

fn moving_reset_observation_belongs_to_anchor(
    anchor: &UsageHistorySample,
    candidate: &UsageHistorySample,
) -> bool {
    // History is evaluated in observation order. A reset timestamp that jumps
    // forward without the observation moving by the same amount is a new
    // period (the boundary seen in the affected database), not a jittered
    // member of the previous period. Do not use saturating subtraction here:
    // accepting a backwards reset would silently merge unrelated periods.
    if candidate.timestamp < anchor.timestamp {
        return false;
    }
    let signed_reset_delta = candidate.reset_at - anchor.reset_at;
    // A moving quota response can wobble by a few seconds between adjacent
    // polls. Keep that same-period jitter, but never allow a large backwards
    // jump to cross a real reset boundary.
    if signed_reset_delta < 0
        && signed_reset_delta.unsigned_abs() > MOVING_RESET_STEP_TOLERANCE_SECONDS as u64
    {
        return false;
    }
    let reset_delta = signed_reset_delta.max(0);
    if candidate.reset_at == anchor.reset_at || reset_delta <= RESET_AT_TOLERANCE_SECONDS {
        return true;
    }
    let timestamp_delta = candidate.timestamp.saturating_sub(anchor.timestamp);
    // The collector can emit two quota snapshots for the same minute while
    // the server advances reset_at between them. Treat that as one moving
    // observation as long as the jump is still bounded; a real boundary is
    // orders of magnitude larger and remains isolated.
    if timestamp_delta == 0 && reset_delta <= MOVING_RESET_GROUP_MAX_DRIFT_SECONDS {
        return true;
    }
    moving_reset_coordinates_form_step(
        anchor.timestamp,
        anchor.reset_at,
        candidate.timestamp,
        candidate.reset_at,
    )
}

fn moving_reset_coordinates_form_step(
    anchor_timestamp: i64,
    anchor_reset_at: i64,
    candidate_timestamp: i64,
    candidate_reset_at: i64,
) -> bool {
    if candidate_timestamp <= anchor_timestamp || candidate_reset_at <= anchor_reset_at {
        return false;
    }
    let timestamp_delta = candidate_timestamp - anchor_timestamp;
    let reset_delta = candidate_reset_at - anchor_reset_at;
    let anchor_horizon = anchor_reset_at.saturating_sub(anchor_timestamp);
    let candidate_horizon = candidate_reset_at.saturating_sub(candidate_timestamp);
    reset_delta <= MOVING_RESET_GROUP_MAX_DRIFT_SECONDS
        && anchor_horizon >= MOVING_RESET_MIN_HORIZON_SECONDS
        && candidate_horizon >= MOVING_RESET_MIN_HORIZON_SECONDS
        && anchor_horizon.abs_diff(candidate_horizon) <= MOVING_RESET_STEP_TOLERANCE_SECONDS as u64
        && reset_delta.abs_diff(timestamp_delta) <= MOVING_RESET_STEP_TOLERANCE_SECONDS as u64
}

fn reset_sample_groups(samples: &[UsageHistorySample]) -> Vec<ResetSampleGroup> {
    let mut sorted = display_history_samples(samples)
        .into_iter()
        .cloned()
        .collect::<Vec<_>>();
    // The wire payload is an observation timeline. Sort by observation first
    // so a rolling reset can be joined one step at a time even when its
    // cumulative drift is hours. A true period boundary has a large reset
    // jump at essentially the same observation timestamp and starts a new
    // group. Equal-reset fragments are coalesced below so legacy singleton
    // quota rows cannot split a spend period.
    sorted.sort_by_key(|sample| (sample.timestamp, sample.reset_at));

    // A far reset observed in the same acquisition timestamp may join a
    // moving sequence only when a strictly later observation continues from
    // that reset. Build that existence proof once by sweeping timestamp
    // batches backwards; repeatedly scanning the remaining history here made
    // one malformed burst quadratic in the retained row count.
    let mut has_forward_observation = vec![false; sorted.len()];
    let mut later_resets = BTreeSet::<i64>::new();
    let mut batch_end = sorted.len();
    while batch_end > 0 {
        let timestamp = sorted[batch_end - 1].timestamp;
        let mut batch_start = batch_end - 1;
        while batch_start > 0 && sorted[batch_start - 1].timestamp == timestamp {
            batch_start -= 1;
        }
        for candidate_index in batch_start..batch_end {
            let candidate_reset = sorted[candidate_index].reset_at;
            has_forward_observation[candidate_index] = later_resets
                .range(
                    candidate_reset
                        ..=candidate_reset.saturating_add(MOVING_RESET_GROUP_MAX_DRIFT_SECONDS),
                )
                .next()
                .is_some();
        }
        for sample in &sorted[batch_start..batch_end] {
            later_resets.insert(sample.reset_at);
        }
        batch_end = batch_start;
    }

    let mut groups = Vec::new();
    let mut index = 0;
    while let Some(anchor) = sorted.get(index).cloned() {
        let mut members = Vec::new();
        let mut canonical_reset_at = anchor.reset_at;
        let mut moving_started = false;
        while let Some(candidate) = sorted.get(index) {
            let previous = members.last().unwrap_or(&anchor);
            // Several reset values at one exact observation timestamp are
            // legitimate only after the sequence has already demonstrated a
            // forward-moving timeline. Without this guard, unrelated
            // same-timestamp reset IDs would chain into one period.
            if !moving_started
                && candidate.timestamp == anchor.timestamp
                && candidate.reset_at.abs_diff(anchor.reset_at) > RESET_AT_TOLERANCE_SECONDS as u64
            {
                if !has_forward_observation[index] {
                    break;
                }
            }
            if !moving_started
                && candidate.reset_at < anchor.reset_at
                && candidate.reset_at.abs_diff(anchor.reset_at) > RESET_AT_TOLERANCE_SECONDS as u64
            {
                break;
            }
            if !moving_reset_observation_belongs_to_anchor(
                if moving_started { previous } else { &anchor },
                candidate,
            ) {
                break;
            }
            if candidate.timestamp > anchor.timestamp && candidate.reset_at > anchor.reset_at {
                moving_started = true;
            }
            canonical_reset_at = canonical_reset_at.max(candidate.reset_at);
            members.push(candidate.clone());
            index += 1;
        }
        groups.push(ResetSampleGroup {
            canonical_reset_at,
            start: members
                .iter()
                .map(|sample| sample.timestamp)
                .min()
                .unwrap_or(anchor.timestamp),
            samples: members,
        });
    }
    // Exact reset IDs remain one candidate cycle even when a transient reset
    // observation is interleaved at the same minute. Nearby reset IDs are not
    // merged here: only the externally authoritative current reset may join
    // aliases, in `authoritative_history_projection_samples`.
    let mut exact_merged: Vec<ResetSampleGroup> = Vec::with_capacity(groups.len());
    let mut exact_indexes = BTreeMap::<i64, usize>::new();
    for mut group in groups {
        if let Some(&index) = exact_indexes.get(&group.canonical_reset_at) {
            let existing = &mut exact_merged[index];
            existing.start = existing.start.min(group.start);
            existing.samples.append(&mut group.samples);
        } else {
            exact_indexes.insert(group.canonical_reset_at, exact_merged.len());
            exact_merged.push(group);
        }
    }
    for group in &mut exact_merged {
        group
            .samples
            .sort_by_key(|sample| (sample.timestamp, sample.reset_at));
    }
    exact_merged.sort_by_key(|group| (group.start, group.canonical_reset_at));
    exact_merged
}

/// Groups reset observations by an anchored sixty-second window, with a
/// bounded moving-reset exception for snapshots whose reset and observation
/// timestamps advance together. The anchor is never advanced by a member of
/// the group, which prevents a chain of small jitters from swallowing a
/// distinct period.
fn history_periods_for_samples(
    samples: &[UsageHistorySample],
    now: i64,
    current_reset_at: Option<i64>,
) -> Vec<HistoryPeriod> {
    let groups = reset_sample_groups(samples);
    let current_group_reset = nearest_current_reset(
        groups.iter().map(|group| group.canonical_reset_at),
        current_reset_at,
        now,
    );

    // Groups are ordered by start. Every member of one equal-start batch has
    // the same next strictly later start, so resolve it once per batch rather
    // than scanning the suffix once per period.
    let mut next_starts = vec![None; groups.len()];
    let mut next_distinct_start = None;
    let mut batch_end = groups.len();
    while batch_end > 0 {
        let start = groups[batch_end - 1].start;
        let mut batch_start = batch_end - 1;
        while batch_start > 0 && groups[batch_start - 1].start == start {
            batch_start -= 1;
        }
        next_starts[batch_start..batch_end].fill(next_distinct_start);
        next_distinct_start = Some(start);
        batch_end = batch_start;
    }

    let mut periods = groups
        .iter()
        .enumerate()
        .map(|(index, group)| {
            // A legacy database can contain an unrelated singleton at the
            // exact same observation minute. It is its own period, but it is
            // not a boundary for the selected spend period; use the next
            // strictly later observation as the visual end instead of
            // collapsing the graph to a zero-width interval.
            let next_start = next_starts[index];
            let period_end = next_start.map_or(group.canonical_reset_at, |next| {
                group.canonical_reset_at.min(next)
            });
            let is_current = current_group_reset == Some(group.canonical_reset_at);
            let end = if is_current {
                now.max(group.start).min(group.canonical_reset_at)
            } else {
                period_end
            };
            // Labels are a presentation concern. Production UI labels are
            // rebuilt by `CodexInfoState::history_periods` with the one
            // startup-pinned I18n/timezone instance. The test-only label
            // keeps the legacy grouping fixtures readable without allowing a
            // fixed JST formatter into the runtime path.
            #[cfg(test)]
            let mut label = format_period_label(group.start, period_end);
            #[cfg(not(test))]
            let label = String::new();
            #[cfg(test)]
            if is_current {
                label.push_str("（現在）");
            }
            HistoryPeriod {
                canonical_reset_at: group.canonical_reset_at,
                start: group.start,
                end,
                label,
            }
        })
        .collect::<Vec<_>>();
    // A burst of several reset groups can share the same observed start and
    // therefore the same base interval label. ComboBox selection must never
    // rely on an ambiguous label, so only colliding labels receive the
    // canonical reset timestamp as a deterministic, user-readable suffix.
    #[cfg(test)]
    {
        let base_labels = periods
            .iter()
            .map(|period| period.label.clone())
            .collect::<Vec<_>>();
        let mut label_counts = BTreeMap::<String, usize>::new();
        let mut start_counts = BTreeMap::<i64, usize>::new();
        for period in &periods {
            *label_counts.entry(period.label.clone()).or_default() += 1;
            *start_counts.entry(period.start).or_default() += 1;
        }
        for index in 0..periods.len() {
            if label_counts
                .get(&base_labels[index])
                .is_some_and(|count| *count > 1)
                || start_counts
                    .get(&periods[index].start)
                    .is_some_and(|count| *count > 1)
            {
                let canonical_reset_at = periods[index].canonical_reset_at;
                let reset_label = format_period_timestamp(canonical_reset_at)
                    .unwrap_or_else(|| "時刻不明".into());
                periods[index]
                    .label
                    .push_str(&format!("（期限 {reset_label}）"));
            }
        }
    }
    periods.sort_by(|left, right| {
        right
            .start
            .cmp(&left.start)
            .then_with(|| right.canonical_reset_at.cmp(&left.canonical_reset_at))
    });
    periods
}

fn nearest_current_reset<I>(resets: I, current_reset_at: Option<i64>, now: i64) -> Option<i64>
where
    I: IntoIterator<Item = i64>,
{
    let current = current_reset_at?;
    resets
        .into_iter()
        .filter(|reset_at| now < *reset_at)
        .filter(|reset_at| current.abs_diff(*reset_at) <= RESET_AT_TOLERANCE_SECONDS as u64)
        .min_by(|left, right| {
            current
                .abs_diff(*left)
                .cmp(&current.abs_diff(*right))
                .then_with(|| right.cmp(left))
        })
}

fn current_history_period_reset(
    periods: &[HistoryPeriod],
    current_reset_at: Option<i64>,
    now: i64,
) -> Option<i64> {
    nearest_current_reset(
        periods.iter().map(|period| period.canonical_reset_at),
        current_reset_at,
        now,
    )
}

/// Build the shared presentation/publication view without mutating retained
/// history. The caller supplies already-canonical samples, so the current
/// quota reset identifies one structurally proven cycle without inspecting
/// quota or model values. Samples from that cycle which precede its
/// authoritative window are retained in SQLite but are not part of the public
/// period.
fn authoritative_history_projection_samples(
    samples: &[UsageHistorySample],
    current_reset_at: Option<i64>,
    window_seconds: i64,
    observed_at: i64,
) -> Vec<UsageHistorySample> {
    let Some(canonical_reset_at) = nearest_current_reset(
        samples.iter().map(|sample| sample.reset_at),
        current_reset_at,
        observed_at,
    ) else {
        return samples.to_vec();
    };
    let Some(authoritative_start) = (window_seconds > 0)
        .then(|| canonical_reset_at.checked_sub(window_seconds))
        .flatten()
        .and_then(minute_start)
    else {
        return samples.to_vec();
    };

    samples
        .iter()
        .filter_map(|sample| {
            let current_alias =
                canonical_reset_at.abs_diff(sample.reset_at) <= RESET_AT_TOLERANCE_SECONDS as u64;
            if current_alias && sample.timestamp < authoritative_start {
                return None;
            }
            let mut projected = sample.clone();
            if current_alias {
                projected.reset_at = canonical_reset_at;
            }
            Some(projected)
        })
        .collect()
}

/// Apply the authoritative quota bounds to the current raw period only.
///
/// `UsageHistory` remains the owner of raw inventory and historical grouping.
/// This bounded projection gives current consumers the quota reset/window
/// boundary without deleting or shape-filtering any stored sample. The sample
/// projection above and this period projection use the same boundary; every
/// other mismatch remains subject to the strict REST validator.
fn apply_authoritative_current_bounds(
    mut periods: Vec<HistoryPeriod>,
    _samples: &[UsageHistorySample],
    current_reset_at: Option<i64>,
    window_seconds: i64,
    observed_at: i64,
) -> Vec<HistoryPeriod> {
    // Use the same deterministic nearest-alias decision as the current-period
    // marker. Picking the first tolerant match can widen a different reset
    // fragment and make one sample belong to two public periods.
    let Some(canonical_reset_at) =
        current_history_period_reset(&periods, current_reset_at, observed_at)
    else {
        return periods;
    };
    let Some(current_index) = periods
        .iter()
        .position(|period| period.canonical_reset_at == canonical_reset_at)
    else {
        return periods;
    };
    let Some(authoritative_start) = (window_seconds > 0)
        .then(|| canonical_reset_at.checked_sub(window_seconds))
        .flatten()
    else {
        periods.remove(current_index);
        return periods;
    };
    let Some(start) = minute_start(authoritative_start) else {
        periods.remove(current_index);
        return periods;
    };
    let end = canonical_reset_at.min(observed_at);
    if end < start {
        periods.remove(current_index);
        return periods;
    }

    periods[current_index].start = start;
    periods[current_index].end = end;
    periods
}

#[derive(Clone, Copy, Debug)]
struct ResetGroupFacts {
    end: i64,
    has_quota: bool,
    observes_multiple_minutes: bool,
}

fn reset_group_facts(groups: &[ResetSampleGroup]) -> Vec<ResetGroupFacts> {
    groups
        .iter()
        .map(|group| {
            let first_minute = group
                .samples
                .first()
                .map(|sample| sample.timestamp.div_euclid(60));
            let mut facts = ResetGroupFacts {
                end: group.start,
                has_quota: false,
                observes_multiple_minutes: false,
            };
            for sample in &group.samples {
                facts.end = facts.end.max(sample.timestamp);
                facts.has_quota |= sample.remaining_percent >= 0.0;
                facts.observes_multiple_minutes |=
                    first_minute.is_some_and(|minute| sample.timestamp.div_euclid(60) != minute);
            }
            facts
        })
        .collect()
}

fn structurally_moving_reset_groups(groups: &[ResetSampleGroup]) -> Vec<bool> {
    let mut moving = groups
        .iter()
        .map(|group| {
            group.samples.windows(2).any(|pair| {
                moving_reset_coordinates_form_step(
                    pair[0].timestamp,
                    pair[0].reset_at,
                    pair[1].timestamp,
                    pair[1].reset_at,
                )
            })
        })
        .collect::<Vec<_>>();
    // Concurrent stable observations can split a rolling reset response into
    // singleton groups. Join only its structural trajectory: observation and
    // reset advance together within the same bounded acquisition interval.
    // Exact-reset groups are unique and ordered by start, so an active reset
    // index limits comparisons to the existing bounded reset/time window.
    let mut active_by_reset = BTreeMap::<i64, usize>::new();
    let mut oldest_active = 0;
    for right in 0..groups.len() {
        let minimum_start = groups[right]
            .start
            .saturating_sub(MOVING_RESET_GROUP_MAX_DRIFT_SECONDS);
        while oldest_active < right && groups[oldest_active].start < minimum_start {
            let reset_at = groups[oldest_active].canonical_reset_at;
            if active_by_reset.get(&reset_at) == Some(&oldest_active) {
                active_by_reset.remove(&reset_at);
            }
            oldest_active += 1;
        }
        let minimum_reset = groups[right]
            .canonical_reset_at
            .saturating_sub(MOVING_RESET_GROUP_MAX_DRIFT_SECONDS);
        for &left in active_by_reset
            .range(minimum_reset..groups[right].canonical_reset_at)
            .map(|(_, index)| index)
        {
            if moving_reset_coordinates_form_step(
                groups[left].start,
                groups[left].canonical_reset_at,
                groups[right].start,
                groups[right].canonical_reset_at,
            ) {
                moving[left] = true;
                moving[right] = true;
            }
        }
        active_by_reset.insert(groups[right].canonical_reset_at, right);
    }
    moving
}

fn reset_group_confirms_fixed_transition(facts: ResetGroupFacts, moving: bool) -> bool {
    !moving && facts.has_quota && facts.observes_multiple_minutes
}

#[derive(Debug)]
struct ActiveResetEnds {
    leaf_count: usize,
    minima: Vec<Option<(i64, usize)>>,
}

impl ActiveResetEnds {
    fn new(reset_count: usize) -> Self {
        let leaf_count = reset_count.next_power_of_two().max(1);
        Self {
            leaf_count,
            minima: vec![None; leaf_count * 2],
        }
    }

    fn earlier(left: Option<(i64, usize)>, right: Option<(i64, usize)>) -> Option<(i64, usize)> {
        match (left, right) {
            (Some(left), Some(right)) => Some(left.min(right)),
            (Some(value), None) | (None, Some(value)) => Some(value),
            (None, None) => None,
        }
    }

    fn update(&mut self, position: usize, value: Option<(i64, usize)>) {
        let mut node = self.leaf_count + position;
        self.minima[node] = value;
        while node > 1 {
            node /= 2;
            self.minima[node] = Self::earlier(self.minima[node * 2], self.minima[node * 2 + 1]);
        }
    }

    fn minimum_before(&self, end: usize) -> Option<(i64, usize)> {
        let mut left = self.leaf_count;
        let mut right = self.leaf_count + end;
        let mut minimum = None;
        while left < right {
            if left % 2 == 1 {
                minimum = Self::earlier(minimum, self.minima[left]);
                left += 1;
            }
            if right % 2 == 1 {
                right -= 1;
                minimum = Self::earlier(minimum, self.minima[right]);
            }
            left /= 2;
            right /= 2;
        }
        minimum
    }
}

fn reset_group_transition_starts(
    groups: &[ResetSampleGroup],
    moving_groups: &[bool],
) -> Vec<Option<i64>> {
    if groups.is_empty() {
        return Vec::new();
    }
    let facts = reset_group_facts(groups);
    let reset_ends = groups
        .iter()
        .zip(&facts)
        .map(|(group, facts)| (group.canonical_reset_at, facts.end))
        .collect::<BTreeMap<_, _>>();
    let family_ends = groups
        .iter()
        .zip(&facts)
        .map(|(group, facts)| {
            reset_ends
                .range(
                    group
                        .canonical_reset_at
                        .saturating_sub(RESET_AT_TOLERANCE_SECONDS)
                        ..=group
                            .canonical_reset_at
                            .saturating_add(RESET_AT_TOLERANCE_SECONDS),
                )
                .map(|(_, end)| *end)
                .max()
                .unwrap_or(facts.end)
        })
        .collect::<Vec<_>>();
    let mut reset_values = groups
        .iter()
        .map(|group| group.canonical_reset_at)
        .collect::<Vec<_>>();
    reset_values.sort_unstable();
    reset_values.dedup();
    let reset_positions = groups
        .iter()
        .map(|group| {
            reset_values
                .binary_search(&group.canonical_reset_at)
                .expect("group reset must exist in its reset index")
        })
        .collect::<Vec<_>>();

    // Sweep later candidate cycles in observation order. The segment tree
    // owns only earlier groups which still overlap this start. A confirmed
    // fixed transition removes every eligible lower-reset group; otherwise
    // only groups ending before the candidate's reset-family tail qualify.
    // Each old group is removed at most once, at its earliest proven boundary.
    let mut transition_starts = vec![None; groups.len()];
    let mut active = vec![false; groups.len()];
    let mut active_ends = ActiveResetEnds::new(reset_values.len());
    let mut expirations = BinaryHeap::<Reverse<(i64, usize)>>::new();
    let mut batch_start = 0;
    while batch_start < groups.len() {
        let candidate_start = groups[batch_start].start;
        while let Some(Reverse((end, index))) = expirations.peek().copied() {
            if end >= candidate_start {
                break;
            }
            expirations.pop();
            if active[index] {
                active[index] = false;
                active_ends.update(reset_positions[index], None);
            }
        }
        let mut batch_end = batch_start + 1;
        while batch_end < groups.len() && groups[batch_end].start == candidate_start {
            batch_end += 1;
        }
        for candidate in batch_start..batch_end {
            let lower_reset_count = reset_values.partition_point(|reset_at| {
                reset_at.saturating_add(RESET_AT_TOLERANCE_SECONDS)
                    < groups[candidate].canonical_reset_at
            });
            let confirmed =
                reset_group_confirms_fixed_transition(facts[candidate], moving_groups[candidate]);
            while let Some((prior_end, prior)) = active_ends.minimum_before(lower_reset_count) {
                if !confirmed && prior_end >= family_ends[candidate] {
                    break;
                }
                transition_starts[prior] = Some(candidate_start);
                active[prior] = false;
                active_ends.update(reset_positions[prior], None);
            }
        }
        for index in batch_start..batch_end {
            active[index] = true;
            active_ends.update(reset_positions[index], Some((facts[index].end, index)));
            expirations.push(Reverse((facts[index].end, index)));
        }
        batch_start = batch_end;
    }
    transition_starts
}

fn shadowed_moving_reset_groups(
    groups: &[ResetSampleGroup],
    moving_groups: &[bool],
    facts: &[ResetGroupFacts],
) -> Vec<bool> {
    let mut shadowed = vec![false; groups.len()];
    let mut prior_quota_max_end = None::<i64>;
    let mut batch_start = 0;
    while batch_start < groups.len() {
        let start = groups[batch_start].start;
        let mut batch_end = batch_start + 1;
        while batch_end < groups.len() && groups[batch_end].start == start {
            batch_end += 1;
        }
        for index in batch_start..batch_end {
            shadowed[index] = moving_groups[index]
                && prior_quota_max_end.is_some_and(|end| end > facts[index].end);
        }
        for facts in &facts[batch_start..batch_end] {
            if facts.has_quota {
                prior_quota_max_end =
                    Some(prior_quota_max_end.map_or(facts.end, |end| end.max(facts.end)));
            }
        }
        batch_start = batch_end;
    }
    shadowed
}

/// Derive the readable history view without changing raw SQLite rows.
///
/// This is a total projection: source anomalies never reject otherwise valid
/// usage. Cycle decisions use only observation time, reset time and quota
/// presence. Within one proven cycle/minute, aliases may contribute one quota
/// value and one already-observed dominant cumulative row; values are never
/// fabricated or assembled component-by-component. If the source cannot prove
/// one owner or one value for a minute, only that minute is omitted so the UI
/// can render it as missing while all other periods remain readable.
fn canonicalize_public_history_samples(samples: &[UsageHistorySample]) -> Vec<UsageHistorySample> {
    let mut groups = reset_sample_groups(samples);
    let moving_groups = structurally_moving_reset_groups(&groups);
    // A later reset which starts inside an older candidate and continues past
    // it is a confirmed forward transition. Remove only the stale tail of the
    // older candidate from that boundary onward. Conversely, a short later
    // reset wholly enclosed by the older cycle is shadowed below and therefore
    // cannot cut the continuing cycle. This uses reset/timestamp structure,
    // never quota percentages or model values.
    let transition_starts = reset_group_transition_starts(&groups, &moving_groups);
    for (group, transition_start) in groups.iter_mut().zip(transition_starts) {
        if let Some(transition_start) = transition_start {
            group
                .samples
                .retain(|sample| sample.timestamp < transition_start);
        }
    }
    groups.retain(|group| !group.samples.is_empty());
    // A reset trajectory which advances with observation time but is wholly
    // enclosed by one stable quota cycle is a transient source outage, not a
    // period. Fixed reset groups are never removed here: their shared minutes
    // are resolved below and their non-conflicting minutes remain readable.
    // Transition tails were resolved first so an older reset cannot hide a
    // fixed newer cycle which has repeated quota observations.
    let moving_groups = structurally_moving_reset_groups(&groups);
    let facts = reset_group_facts(&groups);
    let shadowed = shadowed_moving_reset_groups(&groups, &moving_groups, &facts);
    groups = groups
        .into_iter()
        .enumerate()
        .filter_map(|(index, group)| (!shadowed[index]).then_some(group))
        .collect();
    let facts = reset_group_facts(&groups);
    let mut minute_groups = BTreeMap::<i64, Vec<usize>>::new();
    for (group_index, group) in groups.iter().enumerate() {
        for sample in &group.samples {
            let owners = minute_groups
                .entry(sample.timestamp.div_euclid(60) * 60)
                .or_default();
            if owners.last() != Some(&group_index) {
                owners.push(group_index);
            }
        }
    }

    // Minute storage makes the last bucket of one cycle and the first bucket
    // of the next cycle share a timestamp when the real boundary has seconds.
    // The later cycle owns that bucket only when it starts there and continues
    // afterward, while every earlier cycle ends there. Any other overlap is
    // still ambiguous and must not be published.
    let mut boundary_minute_owners = BTreeMap::<i64, usize>::new();
    let mut ambiguous_minutes = BTreeSet::<i64>::new();
    for (minute, group_indexes) in minute_groups
        .iter()
        .filter(|(_, group_indexes)| group_indexes.len() > 1)
    {
        // A quota observation is direct evidence for the reset cycle that
        // owned this minute. Model-history-only rows can enrich a proven
        // cycle, but cannot displace that authority or make the whole minute
        // unreadable. This decision depends on source capability, never on
        // dollar/token magnitude.
        let quota_owners = group_indexes
            .iter()
            .copied()
            .filter(|group_index| facts[*group_index].has_quota)
            .collect::<Vec<_>>();
        if let [owner] = quota_owners.as_slice() {
            boundary_minute_owners.insert(*minute, *owner);
            continue;
        }
        let continuing = group_indexes
            .iter()
            .copied()
            .filter(|group_index| {
                let group = &groups[*group_index];
                group.start == *minute && facts[*group_index].end.div_euclid(60) * 60 > *minute
            })
            .collect::<Vec<_>>();
        let [owner] = continuing.as_slice() else {
            ambiguous_minutes.insert(*minute);
            continue;
        };
        if group_indexes.iter().copied().any(|group_index| {
            group_index != *owner && facts[group_index].end.div_euclid(60) * 60 > *minute
        }) {
            ambiguous_minutes.insert(*minute);
            continue;
        }
        boundary_minute_owners.insert(*minute, *owner);
    }

    let mut canonical = Vec::with_capacity(samples.len());
    for (group_index, group) in groups.into_iter().enumerate() {
        let mut rows = group
            .samples
            .into_iter()
            .filter(|sample| {
                let minute = sample.timestamp.div_euclid(60) * 60;
                !ambiguous_minutes.contains(&minute)
                    && boundary_minute_owners
                        .get(&minute)
                        .is_none_or(|owner| *owner == group_index)
            })
            .collect::<Vec<_>>();
        if rows.is_empty() {
            continue;
        }
        rows.sort_by_key(|sample| {
            (
                sample.timestamp.div_euclid(60) * 60,
                sample.timestamp,
                sample.reset_at,
            )
        });
        let mut index = 0;
        while index < rows.len() {
            let minute = rows[index].timestamp.div_euclid(60) * 60;
            let start = index;
            while index < rows.len() && rows[index].timestamp.div_euclid(60) * 60 == minute {
                index += 1;
            }
            let minute_rows = &rows[start..index];
            let mut quota = None;
            let mut quota_conflict = false;
            for row in minute_rows
                .iter()
                .filter(|row| row.remaining_percent >= 0.0)
            {
                if quota.is_some_and(|existing| existing != row.remaining_percent) {
                    quota_conflict = true;
                    break;
                }
                quota = Some(row.remaining_percent);
            }
            if quota_conflict {
                continue;
            }
            let first = &minute_rows[0];
            let mut maximums = (
                first.sol_dollars,
                first.terra_dollars,
                first.luna_dollars,
                first.sol_tokens,
                first.terra_tokens,
                first.luna_tokens,
            );
            for row in &minute_rows[1..] {
                maximums.0 = maximums.0.max(row.sol_dollars);
                maximums.1 = maximums.1.max(row.terra_dollars);
                maximums.2 = maximums.2.max(row.luna_dollars);
                maximums.3 = maximums.3.max(row.sol_tokens);
                maximums.4 = maximums.4.max(row.terra_tokens);
                maximums.5 = maximums.5.max(row.luna_tokens);
            }
            let dominant = minute_rows
                .iter()
                .rev()
                .find(|candidate| {
                    candidate.sol_dollars >= maximums.0
                        && candidate.terra_dollars >= maximums.1
                        && candidate.luna_dollars >= maximums.2
                        && candidate.sol_tokens >= maximums.3
                        && candidate.terra_tokens >= maximums.4
                        && candidate.luna_tokens >= maximums.5
                })
                .cloned();
            let Some(dominant) = dominant else {
                continue;
            };
            let mut sample = dominant;
            sample.timestamp = minute;
            sample.reset_at = group.canonical_reset_at;
            sample.remaining_percent = quota.unwrap_or(-1.0);
            canonical.push(sample);
        }
    }
    canonical.sort_by_key(|sample| (sample.reset_at, sample.timestamp));
    canonical
}

#[derive(Debug, Default)]
struct UsageHistory {
    db_path: Option<PathBuf>,
    partition_identity: Option<StoragePartitionIdentity>,
    samples: Vec<UsageHistorySample>,
    observations: Vec<usage_store::UsageHistoryObservation>,
    pending_store_samples: Vec<usage_store::UsageHistorySample>,
    pending_store_observations: Vec<usage_store::UsageHistoryObservation>,
    startup_maintenance_done: bool,
}

fn main_sample_from_observation(
    observation: &usage_store::UsageHistoryObservation,
) -> Option<UsageHistorySample> {
    Some(UsageHistorySample {
        timestamp: observation.timestamp,
        reset_at: observation.reset_at,
        remaining_percent: observation.remaining_percent.unwrap_or(-1.0),
        sol_dollars: observation.sol_dollars?,
        terra_dollars: observation.terra_dollars?,
        luna_dollars: observation.luna_dollars?,
        sol_tokens: observation.sol_tokens?,
        terra_tokens: observation.terra_tokens?,
        luna_tokens: observation.luna_tokens?,
    })
}

fn main_sample_from_public_observation(
    observation: &PublicHistoryObservation,
) -> Option<UsageHistorySample> {
    Some(UsageHistorySample {
        timestamp: observation.timestamp,
        reset_at: observation.reset_at,
        remaining_percent: observation.remaining_percent.unwrap_or(-1.0),
        sol_dollars: observation.sol_dollars?,
        terra_dollars: observation.terra_dollars?,
        luna_dollars: observation.luna_dollars?,
        sol_tokens: observation.sol_tokens?,
        terra_tokens: observation.terra_tokens?,
        luna_tokens: observation.luna_tokens?,
    })
}

fn store_observation_from_public(
    observation: &PublicHistoryObservation,
) -> usage_store::UsageHistoryObservation {
    let model_source = match observation.model_source.as_str() {
        "confirmed" => usage_store::ModelSource::Confirmed,
        "unavailable" => usage_store::ModelSource::Unavailable,
        _ => usage_store::ModelSource::LegacyUnknown,
    };
    usage_store::UsageHistoryObservation {
        timestamp: observation.timestamp,
        reset_at: observation.reset_at,
        remaining_percent: observation.remaining_percent,
        sol_dollars: observation.sol_dollars,
        terra_dollars: observation.terra_dollars,
        luna_dollars: observation.luna_dollars,
        sol_tokens: observation.sol_tokens,
        terra_tokens: observation.terra_tokens,
        luna_tokens: observation.luna_tokens,
        model_source,
        model_totals: None,
        model_totals_complete: false,
    }
}

fn v3_model_by_name<'a>(
    models: Option<&'a [PublicHistoryModelUsageV3]>,
    name: &str,
) -> Option<&'a PublicHistoryModelUsageV3> {
    models?.iter().find(|model| model.model == name)
}

fn main_sample_from_public_observation_v3(
    observation: &PublicHistoryObservationV3,
) -> Option<UsageHistorySample> {
    let models = observation.models.as_deref();
    let value = |name: &str| {
        v3_model_by_name(models, name)
            .and_then(|model| model.total_dollars)
            .unwrap_or(if observation.models_complete {
                0.0
            } else {
                -1.0
            })
    };
    let tokens = |name: &str| {
        v3_model_by_name(models, name)
            .map(|model| model.total_tokens)
            .unwrap_or(0)
    };
    Some(UsageHistorySample {
        timestamp: observation.timestamp,
        reset_at: observation.reset_at,
        remaining_percent: observation.remaining_percent.unwrap_or(-1.0),
        sol_dollars: value("SOL"),
        terra_dollars: value("TERRA"),
        luna_dollars: value("LUNA"),
        sol_tokens: tokens("SOL"),
        terra_tokens: tokens("TERRA"),
        luna_tokens: tokens("LUNA"),
    })
}

fn store_observation_from_public_v3(
    observation: &PublicHistoryObservationV3,
) -> usage_store::UsageHistoryObservation {
    let model_source = match observation.model_source.as_str() {
        "confirmed" => usage_store::ModelSource::Confirmed,
        "unavailable" => usage_store::ModelSource::Unavailable,
        _ => usage_store::ModelSource::LegacyUnknown,
    };
    let models = observation.models.as_ref();
    let model_totals = models.map(|models| {
        models
            .iter()
            .map(|model| usage_store::SessionModelTotal {
                model: model.model.clone(),
                total_tokens: model.total_tokens,
                // v3 intentionally omits unknown components.  These fields
                // are only a persistence carrier; graph/UI projections use
                // total_tokens and total_dollars and retain source quality.
                input_tokens: model.input_tokens.unwrap_or(0),
                cached_input_tokens: model.cached_input_tokens.unwrap_or(0),
                output_tokens: model.output_tokens.unwrap_or(0),
                cache_write_input_tokens: model.cache_write_input_tokens,
            })
            .collect::<Vec<_>>()
    });
    usage_store::UsageHistoryObservation {
        timestamp: observation.timestamp,
        reset_at: observation.reset_at,
        remaining_percent: observation.remaining_percent,
        sol_dollars: v3_model_by_name(models.map(Vec::as_slice), "SOL")
            .and_then(|model| model.total_dollars),
        terra_dollars: v3_model_by_name(models.map(Vec::as_slice), "TERRA")
            .and_then(|model| model.total_dollars),
        luna_dollars: v3_model_by_name(models.map(Vec::as_slice), "LUNA")
            .and_then(|model| model.total_dollars),
        sol_tokens: v3_model_by_name(models.map(Vec::as_slice), "SOL")
            .map(|model| model.total_tokens),
        terra_tokens: v3_model_by_name(models.map(Vec::as_slice), "TERRA")
            .map(|model| model.total_tokens),
        luna_tokens: v3_model_by_name(models.map(Vec::as_slice), "LUNA")
            .map(|model| model.total_tokens),
        model_source,
        model_totals,
        model_totals_complete: observation.models_complete,
    }
}

fn prefer_model_source(
    current: usage_store::ModelSource,
    candidate: usage_store::ModelSource,
) -> usage_store::ModelSource {
    match (current, candidate) {
        (usage_store::ModelSource::Confirmed, _) => usage_store::ModelSource::Confirmed,
        (_, usage_store::ModelSource::Confirmed) => usage_store::ModelSource::Confirmed,
        (usage_store::ModelSource::LegacyUnknown, _)
        | (_, usage_store::ModelSource::LegacyUnknown) => usage_store::ModelSource::LegacyUnknown,
        _ => usage_store::ModelSource::Unavailable,
    }
}

/// Attribute each v1-canonical model vector to the source row selected by the
/// same reset-group/dominant-vector canonicalizer. A timestamp-only lookup is
/// unsafe when a legacy singleton or a reset-drift duplicate shares a minute.
fn canonical_model_sources(
    observations: &[usage_store::UsageHistoryObservation],
    canonical_samples: &[UsageHistorySample],
) -> BTreeMap<(i64, i64), usage_store::ModelSource> {
    type ModelVectorKey = (u64, u64, u64, u64, u64, u64);
    let vector_key = |sample: &UsageHistorySample| -> ModelVectorKey {
        (
            sample.sol_dollars.to_bits(),
            sample.terra_dollars.to_bits(),
            sample.luna_dollars.to_bits(),
            sample.sol_tokens,
            sample.terra_tokens,
            sample.luna_tokens,
        )
    };
    let complete = observations
        .iter()
        .filter(|observation| observation.model_source != usage_store::ModelSource::Unavailable)
        .filter_map(|observation| {
            main_sample_from_observation(observation).map(|sample| (observation, sample))
        })
        .collect::<Vec<_>>();
    let complete_samples = complete
        .iter()
        .map(|(_, sample)| sample.clone())
        .collect::<Vec<_>>();
    let raw_groups = reset_sample_groups(&complete_samples);
    let mut raw_owners = BTreeMap::<(i64, i64, ModelVectorKey), i64>::new();
    for group in &raw_groups {
        for member in &group.samples {
            raw_owners.insert(
                (member.reset_at, member.timestamp, vector_key(member)),
                group.canonical_reset_at,
            );
        }
    }
    let mut canonical_sources =
        BTreeMap::<(i64, i64, ModelVectorKey), usage_store::ModelSource>::new();
    for (observation, sample) in complete {
        let Some(&canonical_reset_at) =
            raw_owners.get(&(sample.reset_at, sample.timestamp, vector_key(&sample)))
        else {
            continue;
        };
        canonical_sources
            .entry((
                canonical_reset_at,
                sample.timestamp.div_euclid(60) * 60,
                vector_key(&sample),
            ))
            .and_modify(|current| {
                *current = prefer_model_source(*current, observation.model_source)
            })
            .or_insert(observation.model_source);
    }
    canonical_samples
        .iter()
        .filter_map(|sample| {
            canonical_sources
                .get(&(sample.reset_at, sample.timestamp, vector_key(sample)))
                .copied()
                .map(|source| ((sample.reset_at, sample.timestamp), source))
        })
        .collect()
}

fn canonical_reset_aliases(samples: &[UsageHistorySample]) -> (BTreeMap<i64, i64>, BTreeSet<i64>) {
    let groups = reset_sample_groups(samples);
    let mut aliases = BTreeMap::new();
    let mut canonical_resets = BTreeSet::new();
    for group in groups {
        canonical_resets.insert(group.canonical_reset_at);
        for sample in group.samples {
            aliases
                .entry(sample.reset_at)
                .or_insert(group.canonical_reset_at);
        }
    }
    (aliases, canonical_resets)
}

fn observation_matches_history_period(
    observation: &usage_store::UsageHistoryObservation,
    period: &PublicHistoryPeriod,
    reset_aliases: &BTreeMap<i64, i64>,
    canonical_resets: &BTreeSet<i64>,
) -> bool {
    observation_matches_period_bounds(
        observation,
        period.reset_at,
        period.start_at,
        period.end_at,
        reset_aliases,
        canonical_resets,
    )
}

fn observation_matches_period_bounds(
    observation: &usage_store::UsageHistoryObservation,
    reset_at: i64,
    start_at: i64,
    end_at: i64,
    reset_aliases: &BTreeMap<i64, i64>,
    canonical_resets: &BTreeSet<i64>,
) -> bool {
    if observation.timestamp < start_at || observation.timestamp > end_at {
        return false;
    }
    observation_reset_matches_period(observation, reset_at, reset_aliases, canonical_resets)
}

fn observation_reset_matches_period(
    observation: &usage_store::UsageHistoryObservation,
    reset_at: i64,
    reset_aliases: &BTreeMap<i64, i64>,
    canonical_resets: &BTreeSet<i64>,
) -> bool {
    if reset_aliases.get(&observation.reset_at) == Some(&reset_at) {
        return true;
    }
    if canonical_resets.contains(&reset_at)
        && observation.reset_at >= reset_at.saturating_sub(60)
        && observation.reset_at <= reset_at
    {
        return true;
    };
    canonical_resets.contains(&reset_at)
        && observation.reset_at <= reset_at
        && reset_at.saturating_sub(observation.reset_at) <= MOVING_RESET_GROUP_MAX_DRIFT_SECONDS
}

impl UsageHistory {
    fn resolve_observation(
        existing: usage_store::UsageHistoryObservation,
        incoming: usage_store::UsageHistoryObservation,
    ) -> usage_store::UsageHistoryObservation {
        let preserve_existing = matches!(
            (existing.model_source, incoming.model_source,),
            (
                usage_store::ModelSource::Confirmed | usage_store::ModelSource::LegacyUnknown,
                usage_store::ModelSource::Unavailable,
            )
        );
        if preserve_existing {
            existing
        } else {
            incoming
        }
    }

    fn merge_observation(
        observations: &mut Vec<usage_store::UsageHistoryObservation>,
        incoming: usage_store::UsageHistoryObservation,
    ) {
        let key = (incoming.reset_at, incoming.timestamp);
        debug_assert!(observations.windows(2).all(|window| {
            (window[0].reset_at, window[0].timestamp) <= (window[1].reset_at, window[1].timestamp)
        }));
        match observations.binary_search_by_key(&key, |observation| {
            (observation.reset_at, observation.timestamp)
        }) {
            Ok(index) => {
                let existing = observations[index].clone();
                observations[index] = Self::resolve_observation(existing, incoming);
            }
            Err(index) => observations.insert(index, incoming),
        }
    }

    /// Merge an acquired batch in key order so backfill/replay does not pay a
    /// full vector shift for every observation. Equal keys use the same source
    /// monotonicity as `merge_observation`.
    fn merge_observations(
        observations: &mut Vec<usage_store::UsageHistoryObservation>,
        mut incoming: Vec<usage_store::UsageHistoryObservation>,
    ) {
        if incoming.is_empty() {
            return;
        }
        let key = |observation: &usage_store::UsageHistoryObservation| {
            (observation.reset_at, observation.timestamp)
        };
        debug_assert!(observations
            .windows(2)
            .all(|window| key(&window[0]) <= key(&window[1])));
        incoming.sort_by_key(key);

        let existing = std::mem::take(observations);
        let mut merged = Vec::with_capacity(existing.len() + incoming.len());
        let mut existing_index = 0;
        let mut incoming_index = 0;
        while existing_index < existing.len() && incoming_index < incoming.len() {
            let existing_key = key(&existing[existing_index]);
            let incoming_key = key(&incoming[incoming_index]);
            if existing_key < incoming_key {
                merged.push(existing[existing_index].clone());
                existing_index += 1;
            } else if existing_key > incoming_key {
                merged.push(incoming[incoming_index].clone());
                incoming_index += 1;
            } else {
                let mut selected = existing[existing_index].clone();
                existing_index += 1;
                while existing_index < existing.len()
                    && key(&existing[existing_index]) == existing_key
                {
                    selected =
                        Self::resolve_observation(selected, existing[existing_index].clone());
                    existing_index += 1;
                }
                while incoming_index < incoming.len()
                    && key(&incoming[incoming_index]) == existing_key
                {
                    selected =
                        Self::resolve_observation(selected, incoming[incoming_index].clone());
                    incoming_index += 1;
                }
                merged.push(selected);
            }
        }
        merged.extend(existing[existing_index..].iter().cloned());
        merged.extend(incoming[incoming_index..].iter().cloned());
        *observations = merged;
    }

    fn confirmed_gaps_from_partition(
        partition: &account_scope::AccountPartition,
    ) -> Result<Vec<PublicHistoryGap>, String> {
        match fs::symlink_metadata(&partition.database_path) {
            Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_file() => {
                return Err(format!(
                    "account partition database is not a regular file: {}",
                    partition.database_path.display()
                ));
            }
            Ok(_) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
            Err(error) => return Err(error.to_string()),
        }
        let identity = partition.storage_identity();
        let store = UsageStore::open_read_only_partitioned(&partition.database_path, &identity)
            .map_err(|error| error.to_string())?;
        Ok(store
            .load_confirmed_recorder_gaps()
            .map_err(|error| error.to_string())?
            .into_iter()
            .filter_map(|gap| {
                Some(PublicHistoryGap {
                    gap_id: gap.gap_id,
                    reset_at: gap.reset_at?,
                    start_at: gap.start_at,
                    end_at: gap.end_at,
                    reason: gap.reason,
                })
            })
            .collect())
    }

    #[cfg(test)]
    fn load_from_db_path(db_path: Option<PathBuf>) -> Self {
        Self::load_from_db_path_at(db_path, Utc::now())
    }

    #[cfg(test)]
    fn load_from_db_path_at(db_path: Option<PathBuf>, now: DateTime<Utc>) -> Self {
        let (samples, observations) = db_path
            .as_ref()
            .and_then(|path| UsageStore::open_read_only(path).ok())
            // Startup reads only the recent calendar-month window through the
            // timestamp/reset index. Raw reset aliases may exceed the public
            // minute count; the public canonicalizer owns that logical bound.
            .and_then(|store| store.load_recent_observations(now).ok())
            .map(|observations| {
                let samples = observations
                    .iter()
                    .filter_map(main_sample_from_observation)
                    .collect::<Vec<_>>();
                (samples, observations)
            })
            .unwrap_or_default();
        let mut history = Self {
            db_path,
            partition_identity: None,
            samples,
            observations,
            pending_store_samples: Vec::new(),
            pending_store_observations: Vec::new(),
            startup_maintenance_done: false,
        };
        history.normalize();
        history
    }

    fn load_from_partition(partition: &account_scope::AccountPartition) -> Result<Self, String> {
        let now = Utc::now();
        let identity = partition.storage_identity();
        let observations = match fs::symlink_metadata(&partition.database_path) {
            Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_file() => {
                return Err(format!(
                    "account partition database is not a regular file: {}",
                    partition.database_path.display()
                ));
            }
            Ok(_) => UsageStore::open_read_only_partitioned(&partition.database_path, &identity)
                .and_then(|store| store.load_recent_observations(now))
                .map_err(|error| error.to_string())?,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Vec::new(),
            Err(error) => return Err(error.to_string()),
        };
        let samples = observations
            .iter()
            .filter_map(main_sample_from_observation)
            .collect::<Vec<_>>();
        let mut history = Self {
            db_path: Some(partition.database_path.clone()),
            partition_identity: Some(identity),
            samples,
            observations,
            pending_store_samples: Vec::new(),
            pending_store_observations: Vec::new(),
            startup_maintenance_done: false,
        };
        history.startup_maintenance(now);
        Ok(history)
    }

    fn preview(now: i64, reset_at: i64, costs: ModelDollarTotals) -> Self {
        let fractions = [0.08, 0.28, 0.48, 0.68, 0.88, 1.0];
        let preview_period =
            |period_reset: i64, period_start: i64, period_end: i64, cost_scale: f64| {
                let elapsed = period_end.saturating_sub(period_start).max(1) as f64;
                fractions
                    .into_iter()
                    .enumerate()
                    .map(move |(index, fraction)| {
                        // プレビュー点を現在時刻までの実測可能な範囲へ分散し、
                        // 未来の点を現在時刻へ丸めて同一X座標に重ねない。
                        let timestamp = period_start + (elapsed * fraction) as i64;
                        // The graph preview deliberately includes one repeated
                        // quota endpoint while model totals continue to advance.
                        // This exercises the missing-sample interpolation path in
                        // the actual X11 image instead of only in unit tests.
                        let used_percent = [16.0, 31.0, 31.0, 51.0, 51.0, 86.0][index];
                        // Keep one model snapshot unchanged to show the
                        // legitimate idle interval as horizontal, while the
                        // later repeated quota value still exercises active
                        // interpolation.
                        let scale_fraction = if index == 2 { 0.28 } else { fraction };
                        let sol_scale = (0.18 + 0.82 * scale_fraction) * cost_scale;
                        let terra_scale = (1.0 - 0.65 * scale_fraction).max(0.1) * cost_scale;
                        let luna_scale =
                            (0.35 + 0.65 * (1.0 - scale_fraction).powi(2)).max(0.1) * cost_scale;
                        UsageHistorySample::new_with_usage(
                            timestamp,
                            period_reset,
                            100.0 - used_percent,
                            ModelDollarTotals {
                                sol: costs.sol * sol_scale,
                                terra: costs.terra * terra_scale,
                                luna: costs.luna * luna_scale,
                            },
                            ModelTokenTotals {
                                sol: (159_278_976.0 * sol_scale) as u64,
                                terra: (30_885_887.0 * terra_scale) as u64,
                                luna: (155_294_770.0 * luna_scale) as u64,
                            },
                        )
                    })
            };
        let previous_reset_at = reset_at.saturating_sub(WEEK_SECONDS);
        let previous = preview_period(
            previous_reset_at,
            previous_reset_at.saturating_sub(WEEK_SECONDS),
            previous_reset_at,
            0.72,
        );
        let current = preview_period(
            reset_at,
            reset_at.saturating_sub(WEEK_SECONDS),
            now.min(reset_at),
            1.0,
        );
        let samples = previous.chain(current).collect();
        Self {
            db_path: None,
            partition_identity: None,
            samples,
            observations: Vec::new(),
            pending_store_samples: Vec::new(),
            pending_store_observations: Vec::new(),
            startup_maintenance_done: true,
        }
    }

    /// Performs the one destructive history operation during normal startup.
    ///
    /// The visible in-memory set is always bounded, even if persistent pruning
    /// is unavailable. A storage failure must never expose an old or future row.
    fn startup_maintenance(&mut self, now: DateTime<Utc>) {
        if self.startup_maintenance_done {
            return;
        }
        self.startup_maintenance_done = true;

        let cutoff = three_months_before_utc(now);
        self.samples
            .retain(|sample| sample.timestamp >= cutoff && sample.timestamp <= now.timestamp());
        self.observations.retain(|observation| {
            observation.timestamp >= cutoff && observation.timestamp <= now.timestamp()
        });
        self.normalize();
    }

    #[cfg(test)]
    fn record(&mut self, sample: UsageHistorySample) {
        self.record_with_models(sample, None, false);
    }

    fn record_with_models(
        &mut self,
        sample: UsageHistorySample,
        model_totals: Option<Vec<usage_store::SessionModelTotal>>,
        model_totals_complete: bool,
    ) {
        if !sample.is_valid() {
            return;
        }
        let stored_sample = sample.to_store();
        self.pending_store_samples.push(stored_sample.clone());
        let observation = model_totals
            .map(|totals| {
                let mut observation = usage_store::UsageHistoryObservation::confirmed_with_models(
                    &stored_sample,
                    totals,
                );
                observation.model_totals_complete = model_totals_complete;
                observation
            })
            .unwrap_or_else(|| usage_store::UsageHistoryObservation::confirmed(&stored_sample));
        Self::merge_observation(&mut self.pending_store_observations, observation.clone());
        Self::merge_observation(&mut self.observations, observation);
        let acquisition_end = sample.timestamp;
        self.samples.push(sample);
        self.normalize();
        self.retain_acquisition_window(acquisition_end);
    }

    #[cfg(test)]
    fn apply_backfill_samples(&mut self, reset_at: i64, samples: Vec<UsageHistorySample>) {
        self.apply_backfill_samples_with_models(reset_at, samples, Vec::new(), false);
    }

    fn apply_backfill_samples_with_models(
        &mut self,
        reset_at: i64,
        samples: Vec<UsageHistorySample>,
        model_history: Vec<(i64, Vec<usage_store::SessionModelTotal>)>,
        model_totals_complete: bool,
    ) {
        if samples.is_empty() {
            return;
        }
        let model_history = model_history.into_iter().collect::<BTreeMap<_, _>>();
        let acquisition_end = samples
            .iter()
            .filter(|sample| sample.is_valid())
            .map(|sample| sample.timestamp)
            .max();
        let _ = reset_at;
        let mut backfill_observations = Vec::new();
        for sample in samples {
            if !sample.is_valid() {
                continue;
            }
            let stored_sample = sample.to_store();
            self.pending_store_samples.push(stored_sample.clone());
            let observation = model_history
                .get(&sample.timestamp)
                .cloned()
                .map(|totals| {
                    let mut observation =
                        usage_store::UsageHistoryObservation::confirmed_with_models(
                            &stored_sample,
                            totals,
                        );
                    observation.model_totals_complete = model_totals_complete;
                    observation
                })
                .unwrap_or_else(|| usage_store::UsageHistoryObservation::confirmed(&stored_sample));
            backfill_observations.push(observation);
            self.samples.push(sample);
        }
        Self::merge_observations(
            &mut self.pending_store_observations,
            backfill_observations.clone(),
        );
        Self::merge_observations(&mut self.observations, backfill_observations);
        self.normalize();
        if let Some(acquisition_end) = acquisition_end {
            self.retain_acquisition_window(acquisition_end);
        }
    }

    fn take_pending_store_samples(&mut self) -> Vec<usage_store::UsageHistorySample> {
        std::mem::take(&mut self.pending_store_samples)
    }

    fn take_pending_store_observations(&mut self) -> Vec<usage_store::UsageHistoryObservation> {
        std::mem::take(&mut self.pending_store_observations)
    }

    fn restore_pending_store_samples(&mut self, mut samples: Vec<usage_store::UsageHistorySample>) {
        samples.append(&mut self.pending_store_samples);
        self.pending_store_samples = samples;
    }

    fn restore_pending_store_observations(
        &mut self,
        mut observations: Vec<usage_store::UsageHistoryObservation>,
    ) {
        observations.append(&mut self.pending_store_observations);
        let pending = &mut self.pending_store_observations;
        pending.clear();
        Self::merge_observations(pending, observations);
    }

    fn record_unavailable(
        &mut self,
        timestamp: i64,
        reset_at: i64,
        remaining_percent: Option<f64>,
    ) {
        if timestamp <= 0 || reset_at <= 0 {
            return;
        }
        let observation = usage_store::UsageHistoryObservation::unavailable(
            timestamp.div_euclid(60) * 60,
            reset_at,
            remaining_percent,
        );
        Self::merge_observation(&mut self.pending_store_observations, observation.clone());
        Self::merge_observation(&mut self.observations, observation);
        self.normalize();
        self.retain_acquisition_window(timestamp.div_euclid(60) * 60);
    }

    fn refresh_from_store(&mut self, now: DateTime<Utc>) -> bool {
        let Some(path) = self.db_path.as_ref() else {
            return false;
        };
        let store = match self.partition_identity.as_ref() {
            Some(identity) => UsageStore::open_read_only_partitioned(path, identity),
            None => UsageStore::open_read_only(path),
        };
        let Ok(store) = store else {
            return false;
        };
        let Ok(observations) = store.load_recent_observations(now) else {
            return false;
        };
        self.observations = observations;
        self.samples = self
            .observations
            .iter()
            .filter_map(main_sample_from_observation)
            .into_iter()
            .collect();
        self.normalize();
        true
    }

    fn apply_committed_samples(
        &mut self,
        samples: Vec<usage_store::UsageHistorySample>,
        now: DateTime<Utc>,
    ) -> bool {
        let mut committed = BTreeMap::new();
        for sample in samples.into_iter().map(UsageHistorySample::from_store) {
            if !sample.is_valid()
                || committed
                    .insert((sample.reset_at, sample.timestamp), sample)
                    .is_some()
            {
                return false;
            }
        }
        if committed.is_empty() {
            return true;
        }
        self.samples
            .retain(|sample| !committed.contains_key(&(sample.reset_at, sample.timestamp)));
        self.samples.extend(committed.into_values());
        self.normalize();
        self.retain_acquisition_window(now.timestamp());
        true
    }

    fn apply_committed_observations(
        &mut self,
        observations: Vec<usage_store::UsageHistoryObservation>,
        now: DateTime<Utc>,
    ) -> bool {
        let mut committed = BTreeMap::new();
        for observation in observations {
            if committed
                .insert((observation.reset_at, observation.timestamp), observation)
                .is_some()
            {
                return false;
            }
        }
        self.observations.retain(|observation| {
            !committed.contains_key(&(observation.reset_at, observation.timestamp))
        });
        self.observations.extend(committed.into_values());
        self.observations
            .sort_by_key(|observation| (observation.reset_at, observation.timestamp));
        self.retain_acquisition_window(now.timestamp());
        true
    }

    #[cfg(test)]
    fn canonical_reset_at(&self, reset_at: i64) -> i64 {
        history_periods_for_samples(&self.samples, 0, None)
            .into_iter()
            .find(|period| {
                self.samples.iter().any(|sample| {
                    sample.reset_at.abs_diff(period.canonical_reset_at)
                        <= RESET_AT_TOLERANCE_SECONDS as u64
                        && sample.reset_at.abs_diff(reset_at) <= RESET_AT_TOLERANCE_SECONDS as u64
                })
            })
            .map_or(reset_at, |period| period.canonical_reset_at)
    }

    fn graph_data_for_reset(&self, reset_at: i64) -> String {
        let samples = self.samples_for_reset(Some(reset_at));
        serde_json::to_string(&samples).unwrap_or_else(|_| "[]".into())
    }

    fn reset_periods_desc(&self) -> Vec<i64> {
        history_periods_for_samples(&self.samples, 0, None)
            .into_iter()
            .map(|period| period.canonical_reset_at)
            .collect()
    }

    fn periods(&self, now: i64, current_reset_at: Option<i64>) -> Vec<HistoryPeriod> {
        history_periods_for_samples(&self.samples, now, current_reset_at)
    }

    fn period_for_id(
        &self,
        canonical_reset_at: i64,
        now: i64,
        current_reset_at: Option<i64>,
    ) -> Option<HistoryPeriod> {
        self.periods(now, current_reset_at)
            .into_iter()
            .find(|period| period.canonical_reset_at == canonical_reset_at)
    }

    #[cfg(test)]
    fn period_id_for_label(
        &self,
        label: &str,
        now: i64,
        current_reset_at: Option<i64>,
    ) -> Option<i64> {
        self.periods(now, current_reset_at)
            .into_iter()
            .find(|period| period.label == label)
            .map(|period| period.canonical_reset_at)
    }

    #[cfg(test)]
    fn period_options(&self, now: i64, current_reset_at: Option<i64>) -> Vec<String> {
        let periods = self.periods(now, current_reset_at);
        if periods.is_empty() {
            vec!["履歴なし".into()]
        } else {
            periods.into_iter().map(|period| period.label).collect()
        }
    }

    fn samples_for_reset(&self, reset_at: Option<i64>) -> Vec<UsageHistorySample> {
        let Some(reset_at) = reset_at else {
            return Vec::new();
        };
        let canonical_reset_at = self
            .period_for_id(reset_at, 0, None)
            .map(|period| period.canonical_reset_at)
            .or_else(|| {
                self.periods(0, None)
                    .into_iter()
                    .find(|period| {
                        period.canonical_reset_at.abs_diff(reset_at)
                            <= RESET_AT_TOLERANCE_SECONDS as u64
                    })
                    .map(|period| period.canonical_reset_at)
            });
        let Some(canonical_reset_at) = canonical_reset_at else {
            return Vec::new();
        };
        let selected = reset_sample_groups(&self.samples)
            .into_iter()
            .find(|group| group.canonical_reset_at == canonical_reset_at)
            .map(|group| group.samples)
            .unwrap_or_default();
        // Presentation consumes the same localized, non-synthetic projection
        // as `/v1/details`; an ambiguous minute cannot suppress the rest of
        // the selected period.
        canonicalize_public_history_samples(&selected)
    }

    #[cfg(test)]
    fn canonical_samples(&self) -> Vec<UsageHistorySample> {
        reset_sample_groups(&self.samples)
            .into_iter()
            .flat_map(|group| {
                group.samples.into_iter().map(move |mut sample| {
                    sample.reset_at = group.canonical_reset_at;
                    sample
                })
            })
            .collect()
    }

    fn normalize(&mut self) {
        // Keep every raw observation distinguishable until the sole public
        // HistoryCanonicalizer validates its cycle/minute group. Sorting is
        // inventory order only; it never merges or rewrites sample values.
        self.samples.retain(UsageHistorySample::is_valid);
        self.samples
            .sort_by_key(|sample| (sample.reset_at, sample.timestamp));
        self.observations
            .retain(|observation| observation.timestamp > 0 && observation.reset_at > 0);
        self.observations
            .sort_by_key(|observation| (observation.reset_at, observation.timestamp));
    }

    /// Bounds the in-memory/API/graph working set without deleting SQLite
    /// retention rows. Persistent deletion remains exclusively the three-month
    /// startup prune.
    fn retain_acquisition_window(&mut self, end_timestamp: i64) {
        let Some(end) = DateTime::<Utc>::from_timestamp(end_timestamp, 0) else {
            return;
        };
        let cutoff = one_month_before_utc(end);
        self.samples
            .retain(|sample| sample.timestamp > cutoff && sample.timestamp <= end_timestamp);
        self.observations.retain(|observation| {
            observation.timestamp > cutoff && observation.timestamp <= end_timestamp
        });
    }
}

fn default_codex_root() -> PathBuf {
    std::env::var_os("CODEX_HOME")
        .map(PathBuf::from)
        .or_else(|| std::env::var_os("HOME").map(|home| PathBuf::from(home).join(".codex")))
        .unwrap_or_else(|| PathBuf::from(".codex"))
}

fn validated_configured_root(path: PathBuf) -> Option<PathBuf> {
    security::validate_absolute_root(&path).ok()
}

fn prepared_data_root(path: PathBuf) -> Option<PathBuf> {
    if !path.is_absolute() {
        return None;
    }
    if !path.exists() {
        let ancestor = path.ancestors().find(|ancestor| ancestor.exists())?;
        security::validate_absolute_root(ancestor).ok()?;
        fs::create_dir_all(&path).ok()?;
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(&path, fs::Permissions::from_mode(0o700)).ok()?;
    }
    validated_configured_root(path)
}

fn usage_data_root() -> Option<PathBuf> {
    let path = std::env::var_os("CODEX_INFO_DATA_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(default_codex_root);
    prepared_data_root(path)
}

fn three_months_before_utc(now: DateTime<Utc>) -> i64 {
    now.checked_sub_months(Months::new(3))
        .expect("subtracting three calendar months from UTC now must be representable")
        .timestamp()
}

fn one_month_before_utc(now: DateTime<Utc>) -> i64 {
    now.checked_sub_months(Months::new(1))
        .expect("subtracting one calendar month from UTC now must be representable")
        .timestamp()
}

