#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct GraphModelPoint {
    dollar: f64,
    tokens: f64,
    reliable: bool,
    published: bool,
}

type GraphModelTimelines = BTreeMap<String, BTreeMap<i64, GraphModelPoint>>;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum GraphRemainingOrigin {
    Raw,
    ActivitySmoothed,
    Interpolated,
    BoundedNullHold,
    TerminalNullHold,
    SyntheticTailHold,
    MonotonicHold,
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct GraphRemainingEvidence {
    timestamp: i64,
    raw: Option<f64>,
    effective: f64,
    origin: GraphRemainingOrigin,
}

fn graph_model_value(point: &GraphModelPoint, show_tokens: bool) -> f64 {
    if show_tokens {
        point.tokens
    } else {
        point.dollar
    }
}

fn accepted_graph_model_timelines(
    timelines: &GraphModelTimelines,
    _trusted_complete_minutes: &BTreeSet<i64>,
    show_tokens: bool,
    _confirmed_gaps: &[GraphConfirmedGap],
) -> (GraphModelTimelines, BTreeSet<i64>) {
    let mut accepted = timelines.clone();
    for timeline in accepted.values_mut() {
        let raw = timeline
            .iter()
            .map(|(timestamp, point)| (*timestamp, graph_model_value(point, show_tokens)))
            .collect::<Vec<_>>();
        let isolated = raw
            .windows(3)
            .filter_map(|window| {
                let [left, middle, right] = window else {
                    return None;
                };
                let exact_cadence =
                    middle.0.saturating_sub(left.0) == 60 && right.0.saturating_sub(middle.0) == 60;
                let finite = [left.1, middle.1, right.1]
                    .into_iter()
                    .all(|value| value.is_finite() && value >= 0.0);
                (exact_cadence
                    && finite
                    && left.1 <= right.1
                    && (middle.1 < left.1 || middle.1 > right.1))
                    .then_some(middle.0)
            })
            .collect::<BTreeSet<_>>();
        let mut baseline = None::<f64>;
        for (timestamp, raw_value) in raw {
            let Some(point) = timeline.get_mut(&timestamp) else {
                continue;
            };
            point.reliable = false;
            if !raw_value.is_finite() || raw_value < 0.0 {
                continue;
            }
            let rejected = isolated.contains(&timestamp)
                || baseline.is_some_and(|accepted_value| raw_value < accepted_value);
            if rejected {
                if let Some(accepted_value) = baseline {
                    if show_tokens {
                        point.tokens = accepted_value;
                    } else {
                        point.dollar = accepted_value;
                    }
                }
                continue;
            }
            baseline = Some(raw_value);
            point.reliable = true;
        }
    }

    // Metric anomalies are carried on their own points. They are prediction
    // intervals, not cross-series correction boundaries.
    (accepted, BTreeSet::new())
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct RemainingMarkerPosition {
    x: f64,
    y: f64,
    boundary: i32,
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct UnusedIntervalPosition {
    start: f64,
    width: f64,
    preserve_boundary: bool,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct GraphConfirmedGap {
    start_at: i64,
    end_at: i64,
}

#[cfg(test)]
fn graph_paths(samples: &[&UsageHistorySample], period_start: i64, period_end: i64) -> GraphPaths {
    graph_paths_with_confirmed_gaps(samples, period_start, period_end, &[])
}

#[cfg(test)]
fn graph_paths_with_confirmed_gaps(
    samples: &[&UsageHistorySample],
    period_start: i64,
    period_end: i64,
    confirmed_gaps: &[GraphConfirmedGap],
) -> GraphPaths {
    graph_paths_with_sources(
        samples,
        period_start,
        period_end,
        &BTreeSet::new(),
        confirmed_gaps,
    )
}

fn graph_paths_with_sources(
    samples: &[&UsageHistorySample],
    period_start: i64,
    period_end: i64,
    untrusted_minutes: &BTreeSet<i64>,
    confirmed_gaps: &[GraphConfirmedGap],
) -> GraphPaths {
    let remaining_points = remaining_graph_points_for_metric_with_sources(
        samples,
        period_start,
        period_end,
        false,
        untrusted_minutes,
    );
    let raw_minute = graph_time_endpoints(
        minute_model_spend_for_metric_with_untrusted(samples, false, untrusted_minutes),
        period_start,
        period_end,
    );
    let minute = smooth_model_spend(&raw_minute);
    // Dollar series are independent cumulative values.  The old stacked
    // implementation used the sum here, which made a model's line depend on
    // whether another model was enabled and could make a flat SOL history
    // appear to move.  A shared axis still gives the three lines a meaningful
    // comparison, but its ceiling is the largest individual model value.
    let observed_dollar_max = samples
        .iter()
        .filter_map(|sample| {
            [
                sample.sol_dollars,
                sample.terra_dollars,
                sample.luna_dollars,
            ]
            .into_iter()
            .filter(|value| value.is_finite() && *value >= 0.0)
            .max_by(f64::total_cmp)
        })
        .max_by(f64::total_cmp)
        .unwrap_or(0.0);
    let dollar_max = minute
        .iter()
        .map(|point| point.sol.max(point.terra).max(point.luna))
        .fold(0.0_f64, f64::max);
    let dollar_max = dollar_max.max(observed_dollar_max);
    let has_model_data = dollar_max > 0.0;
    let latest = minute.last().copied().unwrap_or_default();
    let display_latest = latest_reliable_model_spend(samples, false).unwrap_or(latest);
    let has_remaining_observation = samples
        .iter()
        .any(|sample| sample.remaining_percent.is_finite() && sample.remaining_percent >= 0.0);
    // Use the same smoothed endpoint that is rendered by `remaining-path` so
    // the right-edge percentage cannot disagree with the visible line after
    // a non-monotonic reread is clamped.
    let remaining = has_remaining_observation
        .then(|| remaining_points.last().map(|(_, value)| *value))
        .flatten();
    let graph_y = |value: f64, maximum: f64| -> f32 {
        if maximum > 0.0 {
            ((99.0 - value / maximum * 98.0) / 100.0).clamp(0.01, 0.99) as f32
        } else {
            0.99
        }
    };
    // Legacy fixed-column histories still use token evidence for idle even
    // while the visible graph is in dollar mode.
    let raw_token_timelines = ["SOL", "TERRA", "LUNA"]
        .into_iter()
        .map(|name| {
            let timeline = samples
                .iter()
                .filter_map(|sample| {
                    let timestamp = sample.timestamp.div_euclid(60) * 60;
                    if untrusted_minutes.contains(&timestamp) {
                        return None;
                    }
                    let (dollar, tokens) = match name {
                        "SOL" => (sample.sol_dollars, sample.sol_tokens),
                        "TERRA" => (sample.terra_dollars, sample.terra_tokens),
                        _ => (sample.luna_dollars, sample.luna_tokens),
                    };
                    Some((
                        timestamp,
                        GraphModelPoint {
                            dollar,
                            tokens: tokens as f64,
                            reliable: true,
                            published: true,
                        },
                    ))
                })
                .collect::<BTreeMap<_, _>>();
            (name.to_owned(), timeline)
        })
        .collect::<GraphModelTimelines>();
    let (token_timelines, _) = accepted_graph_model_timelines(
        &raw_token_timelines,
        &BTreeSet::new(),
        true,
        confirmed_gaps,
    );
    let unused_intervals = token_idle_interval_positions(
        samples,
        period_start,
        period_end,
        &token_timelines,
        confirmed_gaps,
    );
    let (remaining_solid, remaining_inferred) = remaining_paths_with_evidence(
        &remaining_points,
        samples,
        &raw_minute,
        period_start,
        period_end,
        confirmed_gaps,
    );
    let remaining_path = [remaining_solid.as_str(), remaining_inferred.as_str()]
        .into_iter()
        .filter(|path| !path.is_empty())
        .collect::<Vec<_>>()
        .join(" ");
    GraphPaths {
        remaining: remaining_path,
        remaining_solid,
        remaining_inferred,
        remaining_markers: remaining_marker_positions_on_points(
            &remaining_points,
            period_start,
            period_end,
        ),
        unused_intervals,
        luna: metric_line_path_with_confirmed_gaps(
            &minute,
            period_start,
            period_end,
            dollar_max,
            |point| point.luna,
            confirmed_gaps,
        ),
        terra: metric_line_path_with_confirmed_gaps(
            &minute,
            period_start,
            period_end,
            dollar_max,
            |point| point.terra,
            confirmed_gaps,
        ),
        sol: metric_line_path_with_confirmed_gaps(
            &minute,
            period_start,
            period_end,
            dollar_max,
            |point| point.sol,
            confirmed_gaps,
        ),
        dollar_labels: dollar_axis_labels(dollar_max),
        current_remaining_label: remaining.map(format_percent).unwrap_or_else(|| "—".into()),
        current_sol_label: if has_model_data && model_spend_is_reliable(&display_latest) {
            format!("${:.2}", display_latest.sol)
        } else {
            String::new()
        },
        current_terra_label: if has_model_data && model_spend_is_reliable(&display_latest) {
            format!("${:.2}", display_latest.terra)
        } else {
            String::new()
        },
        current_luna_label: if has_model_data && model_spend_is_reliable(&display_latest) {
            format!("${:.2}", display_latest.luna)
        } else {
            String::new()
        },
        current_remaining_y: graph_y(remaining.unwrap_or(0.0), 100.0),
        current_sol_y: graph_y(display_latest.sol, dollar_max),
        current_terra_y: graph_y(display_latest.terra, dollar_max),
        current_luna_y: graph_y(display_latest.luna, dollar_max),
        current_remaining_point_y: graph_y(remaining.unwrap_or(0.0), 100.0),
        current_sol_point_y: graph_y(display_latest.sol, dollar_max),
        current_terra_point_y: graph_y(display_latest.terra, dollar_max),
        current_luna_point_y: graph_y(display_latest.luna, dollar_max),
        ..GraphPaths::default()
    }
}

