fn graph_minute_points_with_model_timelines(
    samples: &[&UsageHistorySample],
    period_start: i64,
    period_end: i64,
    show_tokens: bool,
    untrusted_minutes: &BTreeSet<i64>,
    model_timelines: &GraphModelTimelines,
) -> Vec<HourlyModelSpend> {
    let mut minute = graph_time_endpoints(
        minute_model_spend_for_metric_with_untrusted(samples, show_tokens, untrusted_minutes),
        period_start,
        period_end,
    );
    for point in &mut minute {
        let value = |name: &str, fallback: f64| {
            let timeline = model_timelines.get(name);
            timeline
                .and_then(|values| values.get(&point.timestamp))
                .or_else(|| {
                    (point.timestamp == period_end)
                        .then(|| {
                            timeline?
                                .range(..=period_end)
                                .next_back()
                                .map(|(_, model)| model)
                        })
                        .flatten()
                })
                .map(|model| graph_model_value(model, show_tokens))
                .unwrap_or(fallback)
        };
        point.sol = value("SOL", point.sol);
        point.terra = value("TERRA", point.terra);
        point.luna = value("LUNA", point.luna);
        point.astra = value("ASTRA", -1.0);
    }
    minute
}

fn graph_model_untrusted_minutes(
    timeline: Option<&BTreeMap<i64, GraphModelPoint>>,
    minute: &[HourlyModelSpend],
    period_end: i64,
) -> BTreeSet<i64> {
    let mut minutes = timeline
        .into_iter()
        .flat_map(BTreeMap::iter)
        .filter(|(_, point)| !point.reliable)
        .map(|(minute, _)| *minute)
        .collect::<BTreeSet<_>>();
    if minute.last().is_some_and(|point| {
        point.timestamp == period_end
            && timeline.is_some_and(|values| !values.contains_key(&period_end))
    }) {
        minutes.insert(period_end);
    }
    minutes
}

fn graph_paths_for_selection_with_sources_and_astra_with_lineage(
    samples: &[&UsageHistorySample],
    period_start: i64,
    period_end: i64,
    show_luna: bool,
    show_terra: bool,
    show_sol: bool,
    show_astra: bool,
    show_tokens: bool,
    untrusted_minutes: &BTreeSet<i64>,
    confirmed_gaps: &[GraphConfirmedGap],
    raw_model_timelines: &GraphModelTimelines,
) -> GraphPaths {
    let mut paths = graph_paths_with_sources(
        samples,
        period_start,
        period_end,
        untrusted_minutes,
        confirmed_gaps,
    );
    // Derive both views from the same raw observations.  Feeding an already
    // accepted display timeline back through the token validator can heal a
    // rejected token regression and makes dollar/token idle bands disagree.
    // Display metric and idle/activity evidence therefore have independent
    // anomaly state, while idle and quota smoothing always use raw tokens.
    let (display_timelines, display_anomaly_starts) = accepted_graph_model_timelines(
        raw_model_timelines,
        &BTreeSet::new(),
        show_tokens,
        confirmed_gaps,
    );
    let (token_timelines, token_anomaly_starts) =
        accepted_graph_model_timelines(raw_model_timelines, &BTreeSet::new(), true, confirmed_gaps);
    let minute = graph_minute_points_with_model_timelines(
        samples,
        period_start,
        period_end,
        show_tokens,
        untrusted_minutes,
        &display_timelines,
    );
    // Quota activity is token-based in both display modes. A cheap model's
    // rounded dollar series must not turn real token movement into idle time.
    let remaining_evidence = remaining_evidence_from_model_timelines(
        samples,
        period_start,
        period_end,
        &token_timelines,
        true,
        confirmed_gaps,
        &token_anomaly_starts,
    );
    let remaining_points = remaining_evidence
        .iter()
        .map(|point| (point.timestamp, point.effective))
        .collect::<Vec<_>>();
    let has_remaining_observation = samples
        .iter()
        .any(|sample| sample.remaining_percent.is_finite() && sample.remaining_percent >= 0.0);
    let model_timeline_evidence = (!token_timelines.is_empty()).then_some((&token_timelines, true));
    if has_remaining_observation {
        if let Some(remaining) = remaining_points.last().map(|(_, value)| *value) {
            let (solid, inferred) = remaining_paths_with_boundaries(
                &remaining_points,
                samples,
                &minute,
                period_start,
                period_end,
                confirmed_gaps,
                &token_anomaly_starts,
                model_timeline_evidence,
                Some(&remaining_evidence),
            );
            paths.remaining = [solid.as_str(), inferred.as_str()]
                .into_iter()
                .filter(|path| !path.is_empty())
                .collect::<Vec<_>>()
                .join(" ");
            paths.remaining_solid = solid;
            paths.remaining_inferred = inferred;
            paths.remaining_markers =
                remaining_marker_positions_on_points(&remaining_points, period_start, period_end);
            paths.current_remaining_label = format_percent(remaining);
            let normalized = ((99.0 - remaining * 0.98) / 100.0).clamp(0.01, 0.99) as f32;
            paths.current_remaining_y = normalized;
            paths.current_remaining_point_y = normalized;
        }
    }
    paths.unused_intervals = token_idle_interval_positions(
        samples,
        period_start,
        period_end,
        &token_timelines,
        confirmed_gaps,
    );
    let maximum = minute
        .iter()
        .map(|point| {
            if show_tokens {
                point
                    .sol
                    .max(point.terra)
                    .max(point.luna)
                    .max(if show_astra {
                        point.astra.max(0.0)
                    } else {
                        0.0
                    })
            } else {
                [
                    show_luna.then_some(point.luna),
                    show_terra.then_some(point.terra),
                    show_sol.then_some(point.sol),
                    show_astra.then_some(point.astra),
                ]
                .into_iter()
                .flatten()
                .fold(0.0_f64, f64::max)
            }
        })
        .fold(0.0_f64, f64::max);
    // Rejected raw pulses must not flatten every accepted series by inflating
    // the Y axis. Windows also derives its maximum from accepted values.
    let scale_maximum = maximum.max(1.0);
    let latest_value = |value: fn(&HourlyModelSpend) -> f64| {
        minute
            .iter()
            .rev()
            .map(value)
            .find(|value| value.is_finite() && *value >= 0.0)
    };
    let model_untrusted = |name: &str| {
        graph_model_untrusted_minutes(display_timelines.get(name), &minute, period_end)
    };
    paths.dollar_labels = if show_tokens {
        token_axis_labels(scale_maximum)
    } else {
        dollar_axis_labels(scale_maximum)
    };
    paths.sol.clear();
    paths.terra.clear();
    paths.luna.clear();
    paths.sol_flat.clear();
    paths.sol_rising.clear();
    paths.sol_inferred.clear();
    paths.terra_flat.clear();
    paths.terra_rising.clear();
    paths.terra_inferred.clear();
    paths.luna_flat.clear();
    paths.luna_rising.clear();
    paths.luna_inferred.clear();
    paths.astra_flat.clear();
    paths.astra_rising.clear();
    paths.astra_inferred.clear();
    paths.current_sol_label.clear();
    paths.current_terra_label.clear();
    paths.current_luna_label.clear();
    paths.current_astra_label.clear();
    paths.current_sol_point_y = 0.99;
    paths.current_terra_point_y = 0.99;
    paths.current_luna_point_y = 0.99;
    paths.current_sol_y = 0.99;
    paths.current_terra_y = 0.99;
    paths.current_luna_y = 0.99;
    paths.current_astra_point_y = 0.99;
    paths.current_astra_y = 0.99;
    let graph_y =
        |value: f64| ((99.0 - value / scale_maximum * 98.0) / 100.0).clamp(0.01, 0.99) as f32;
    if show_luna {
        let (flat, rising, inferred) = split_metric_line_paths_with_boundaries(
            &minute,
            period_start,
            period_end,
            scale_maximum,
            |point| point.luna,
            confirmed_gaps,
            &model_untrusted("LUNA"),
            false,
            &display_anomaly_starts,
        );
        paths.luna_flat = flat;
        paths.luna_rising = rising;
        paths.luna_inferred = inferred;
        paths.luna = [
            paths.luna_flat.as_str(),
            paths.luna_rising.as_str(),
            paths.luna_inferred.as_str(),
        ]
        .into_iter()
        .filter(|path| !path.is_empty())
        .collect::<Vec<_>>()
        .join(" ");
        if let Some(latest) = latest_value(|point| point.luna) {
            paths.current_luna_label = format_metric_value(latest, show_tokens);
            paths.current_luna_y = graph_y(latest);
            paths.current_luna_point_y = paths.current_luna_y;
        }
    }
    if show_terra {
        let (flat, rising, inferred) = split_metric_line_paths_with_boundaries(
            &minute,
            period_start,
            period_end,
            scale_maximum,
            |point| point.terra,
            confirmed_gaps,
            &model_untrusted("TERRA"),
            false,
            &display_anomaly_starts,
        );
        paths.terra_flat = flat;
        paths.terra_rising = rising;
        paths.terra_inferred = inferred;
        paths.terra = [
            paths.terra_flat.as_str(),
            paths.terra_rising.as_str(),
            paths.terra_inferred.as_str(),
        ]
        .into_iter()
        .filter(|path| !path.is_empty())
        .collect::<Vec<_>>()
        .join(" ");
        if let Some(latest) = latest_value(|point| point.terra) {
            paths.current_terra_label = format_metric_value(latest, show_tokens);
            paths.current_terra_y = graph_y(latest);
            paths.current_terra_point_y = paths.current_terra_y;
        }
    }
    if show_sol {
        let (flat, rising, inferred) = split_metric_line_paths_with_boundaries(
            &minute,
            period_start,
            period_end,
            scale_maximum,
            |point| point.sol,
            confirmed_gaps,
            &model_untrusted("SOL"),
            false,
            &display_anomaly_starts,
        );
        paths.sol_flat = flat;
        paths.sol_rising = rising;
        paths.sol_inferred = inferred;
        paths.sol = [
            paths.sol_flat.as_str(),
            paths.sol_rising.as_str(),
            paths.sol_inferred.as_str(),
        ]
        .into_iter()
        .filter(|path| !path.is_empty())
        .collect::<Vec<_>>()
        .join(" ");
        if let Some(latest) = latest_value(|point| point.sol) {
            paths.current_sol_label = format_metric_value(latest, show_tokens);
            paths.current_sol_y = graph_y(latest);
            paths.current_sol_point_y = paths.current_sol_y;
        }
    }
    if show_astra {
        let (flat, rising, inferred) = split_metric_line_paths_with_boundaries(
            &minute,
            period_start,
            period_end,
            scale_maximum,
            |point| point.astra,
            confirmed_gaps,
            &model_untrusted("ASTRA"),
            false,
            &display_anomaly_starts,
        );
        paths.astra_flat = flat;
        paths.astra_rising = rising;
        paths.astra_inferred = inferred;
        if let Some(latest_astra) = minute
            .iter()
            .rev()
            .map(|point| point.astra)
            .find(|value| value.is_finite() && *value >= 0.0)
        {
            paths.current_astra_label = format_metric_value(latest_astra, show_tokens);
            paths.current_astra_y = graph_y(latest_astra);
            paths.current_astra_point_y = paths.current_astra_y;
        }
    }
    paths
}

