    #[test]
    fn public_snapshot_is_whitelisted_and_tracks_auth_state() {
        let assert_empty = |details: &codex_info::server::PublicDetails| {
            assert!(details.observed_at.is_none());
            assert!(!details.authenticated);
            assert!(details.plan_label.is_none());
            assert!(details.quota.is_none());
            assert!(details.models.is_empty());
            assert_eq!(details.active_thread_count, 0);
            assert!(details.history_periods.is_empty());
            assert!(details.history_samples.is_empty());
            assert!(details.history_gaps.is_empty());
            assert!(details.threads.is_empty());
            assert_eq!(details.estimated_cost_label, "概算 —");
        };
        let normal = CodexInfoState::preview("normal");
        let snapshot = normal.public_details();
        assert_eq!(snapshot.state, PublicState::Ready);
        assert!(snapshot.authenticated);
        assert_eq!(snapshot.plan_label.as_deref(), Some("Pro"));
        assert_eq!(
            snapshot.quota.as_ref().map(|quota| quota.remaining_percent),
            Some(14.0)
        );
        assert_eq!(snapshot.models.len(), 3);
        assert_eq!(snapshot.models[0].name, "SOL");
        assert_eq!(snapshot.models[0].input_tokens, 80_000_000);
        assert_eq!(snapshot.models[0].cached_input_tokens, 30_000_000);
        assert_eq!(snapshot.active_thread_count, 1);
        let json = serde_json::to_value(snapshot).expect("public snapshot serializes");
        assert!(json.get("email").is_none());
        assert!(json.get("auth_url").is_none());
        assert!(json.get("error").is_none());
        assert!(json.get("history").is_none());
        assert!(json.get("session_path").is_none());

        let details = normal.public_details();
        assert_eq!(details.models.len(), 3);
        assert!(details.models[0].input_dollars.is_finite());
        assert!(details.models[0].input_dollars > 0.0);
        assert!(!details.history_periods.is_empty());
        assert!(!details.history_samples.is_empty());
        assert!(details.history_gaps.is_empty());
        assert_eq!(details.threads.len(), 1);
        assert_eq!(details.threads[0].model_label, "gpt-5.6-sol");
        let details_json = serde_json::to_value(details).expect("public details serializes");
        assert!(details_json.get("email").is_none());
        assert!(details_json.get("auth_url").is_none());
        assert!(details_json.get("session_path").is_none());

        let auth = CodexInfoState::preview("auth").public_details();
        assert_eq!(auth.state, PublicState::AuthRequired);
        assert_empty(&auth);

        let initializing = CodexInfoState::preview("initializing").public_details();
        assert_eq!(initializing.state, PublicState::Initializing);
        assert_empty(&initializing);

        let mut identity_error = CodexInfoState::preview("normal");
        identity_error.preview = false;
        identity_error.apply_identity_error("identity verification failed".into());
        let error = identity_error.public_details();
        assert_eq!(error.state, PublicState::Error);
        assert_empty(&error);

        let startup = CodexInfoState::preview("startup-loading");
        assert!(startup.authenticated);
        assert!(!startup.has_visible_usage());
        assert!(native_startup_loading(
            startup.authenticated,
            startup.has_visible_usage(),
            startup.local_usage_error,
            startup.account_error.is_some(),
            startup.error.is_some(),
        ));
        assert_eq!(startup.public_details().state, PublicState::Initializing);
        assert!(startup.public_details().models.is_empty());
        assert!(startup.public_details().quota.is_none());
        assert!(startup.public_details().history_samples.is_empty());

        let unlimited = CodexInfoState::preview("unlimited").public_details();
        assert_eq!(unlimited.state, PublicState::Ready);
        assert!(unlimited.quota.is_none());
    }

    #[test]
    fn public_history_uses_one_effective_observed_time_for_admission_and_period_end() {
        const OBSERVED_AT: i64 = 1_800_000_000;
        const RESET_AT: i64 = OBSERVED_AT + 3_600;
        let mut state = CodexInfoState::preview("normal");
        state.last_success_at = Some(OBSERVED_AT);
        state.reset_at = Some(RESET_AT);
        state.window_seconds = 3_600;
        state.history = UsageHistory {
            samples: vec![
                UsageHistorySample::new(OBSERVED_AT, RESET_AT, 50.0, ModelDollarTotals::default()),
                UsageHistorySample::new(
                    OBSERVED_AT + 60,
                    RESET_AT,
                    49.0,
                    ModelDollarTotals::default(),
                ),
            ],
            ..UsageHistory::default()
        };

        let details = state.public_details_candidate_at(OBSERVED_AT + 600);

        assert_eq!(details.observed_at, Some(OBSERVED_AT));
        assert_eq!(
            details
                .history_samples
                .iter()
                .map(|sample| sample.timestamp)
                .collect::<Vec<_>>(),
            [OBSERVED_AT]
        );
        assert!(details
            .history_periods
            .iter()
            .filter(|period| period.current)
            .all(|period| period.end_at == OBSERVED_AT));
        details.validate().unwrap();
    }

    #[test]
    fn startup_load_keeps_dense_alias_history_and_publishes_each_period() {
        let db_path = test_history_path("dense-alias-restart");
        let now = Utc.with_ymd_and_hms(2026, 8, 31, 12, 0, 0).unwrap();
        let current_start = now.timestamp() - 5 * 86_400;
        let previous_reset = current_start;
        let current_reset = current_start + WEEK_SECONDS;
        drop(UsageStore::open(&db_path).unwrap());

        let mut connection = rusqlite::Connection::open(&db_path).unwrap();
        {
            let transaction = connection.transaction().unwrap();
            {
                let mut insert = transaction
                    .prepare(
                        "INSERT INTO usage_history (timestamp, reset_at, remaining_percent, \
                         sol_dollars, terra_dollars, luna_dollars, sol_tokens, terra_tokens, luna_tokens) \
                         VALUES (?1, ?2, 48, ?3, 0, 0, ?4, 0, 0)",
                    )
                    .unwrap();
                for index in 0..usage_store::MAX_RECENT_HISTORY_SAMPLES {
                    let timestamp = now.timestamp()
                        - (usage_store::MAX_RECENT_HISTORY_SAMPLES - 1 - index) as i64 * 60;
                    let reset_at = if timestamp < current_start {
                        previous_reset
                    } else {
                        current_reset
                    };
                    insert
                        .execute(rusqlite::params![
                            timestamp,
                            reset_at,
                            index as f64,
                            index as i64,
                        ])
                        .unwrap();
                }
                insert
                    .execute(rusqlite::params![
                        now.timestamp(),
                        current_reset + 30,
                        usage_store::MAX_RECENT_HISTORY_SAMPLES as f64,
                        usage_store::MAX_RECENT_HISTORY_SAMPLES as i64,
                    ])
                    .unwrap();
            }
            transaction.commit().unwrap();
        }
        drop(connection);

        let history = UsageHistory::load_from_db_path_at(Some(db_path.clone()), now);
        assert_eq!(
            history.samples.len(),
            usage_store::MAX_RECENT_HISTORY_SAMPLES + 1
        );

        let mut state = CodexInfoState::preview("normal");
        state.history = history;
        state.last_success_at = Some(now.timestamp());
        state.reset_at = Some(current_reset);
        state.window_seconds = WEEK_SECONDS;
        let details = state.public_details_candidate_at(now.timestamp());

        assert_eq!(details.history_periods.len(), 2);
        assert_eq!(
            details.history_samples.len(),
            usage_store::MAX_RECENT_HISTORY_SAMPLES
        );
        let expected_timestamps = (0..usage_store::MAX_RECENT_HISTORY_SAMPLES)
            .map(|index| {
                now.timestamp() - (usage_store::MAX_RECENT_HISTORY_SAMPLES - 1 - index) as i64 * 60
            })
            .collect::<Vec<_>>();
        assert_eq!(
            details
                .history_samples
                .iter()
                .map(|sample| sample.timestamp)
                .collect::<Vec<_>>(),
            expected_timestamps
        );
        assert_eq!(
            details
                .history_samples
                .first()
                .map(|sample| sample.timestamp),
            Some(now.timestamp() - (usage_store::MAX_RECENT_HISTORY_SAMPLES - 1) as i64 * 60)
        );
        assert_eq!(
            details
                .history_samples
                .last()
                .map(|sample| sample.timestamp),
            Some(now.timestamp())
        );
        details.validate().unwrap();

        let _ = fs::remove_dir_all(db_path.parent().unwrap());
    }

