    #[test]
    fn quota_projection_and_thread_state_transitions_are_atomic() {
        let mut state = CodexInfoState::preview("normal");
        let previous = state.active_threads.clone();
        let reset_at = state.reset_at.expect("preview quota has reset");
        let history_before = state.history.samples.clone();

        state.apply_usage_event(usage_event(Some(69.0), reset_at));
        assert_eq!(state.remaining_percent, Some(69.0));
        assert_eq!(state.active_threads, previous);
        assert_eq!(state.history.samples, history_before);

        state.apply_thread_result(state.auth_epoch, ActiveThreadUpdate::Failed);
        assert!(state.thread_error);
        assert_eq!(state.active_threads, previous);
        assert_eq!(
            state.public_details().active_thread_count,
            previous.len() as u64
        );
        assert_eq!(state.public_details().threads.len(), previous.len());
        assert_eq!(
            active_thread_rows_at(&state.active_threads, 0).len(),
            previous.len()
        );
        assert_eq!(
            state.status,
            "利用枠は更新しました。スレッド情報の取得に失敗し、実行中の状態は未確認です。"
        );

        let replacement = ActiveThread {
            id: "replacement".into(),
            created_at: Some(60),
            updated_at: 123,
            title: "replacement title".into(),
            model: "gpt-5.6-terra".into(),
            model_label: "gpt-5.6-terra".into(),
            total_tokens: Some(98_765),
            context_usage_tokens: None,
            context_window_tokens: None,
            last_user_message_at: Some(120),
            is_subagent: true,
            parent_thread_id: Some("parent".into()),
            depth: Some(1),
        };
        state.apply_thread_result(
            state.auth_epoch,
            ActiveThreadUpdate::Snapshot(vec![replacement.clone()]),
        );
        assert_eq!(state.active_threads, [replacement]);
        assert!(state.error.is_none());

        state.apply_usage_event(usage_event(Some(67.0), reset_at));
        state.apply_thread_result(state.auth_epoch, ActiveThreadUpdate::NoThread);
        assert!(state.active_threads.is_empty());
    }

    #[test]
    fn periodic_quota_refresh_does_not_overlap_account_generations() {
        let now = Instant::now();
        let mut state = CodexInfoState::preview("normal");
        state.preview = false;
        state.checking = false;
        state.thread_checking = true;
        state.last_poll = now - Duration::from_secs(61);
        state.local_usage_pending = true;
        let (command_tx, commands) = std::sync::mpsc::channel();
        let (_event_tx, event_rx) = std::sync::mpsc::channel();
        state.bridge = super::AppServerBridge {
            tx: command_tx,
            rx: event_rx,
        };

        let _ = state.schedule_resident_refresh(now);
        assert!(commands.try_recv().is_err());

        // Once the current local result reaches a terminal state, the same
        // overdue timer owns exactly one next account request.
        state.local_usage_pending = false;
        let _ = state.schedule_resident_refresh(now);
        assert!(matches!(
            commands.try_recv(),
            Ok(super::AccountCommand::Read)
        ));
        assert!(commands.try_recv().is_err());
    }

    #[test]
    fn rolling_reset_timestamp_drift_is_not_a_new_period() {
        let now = 2_000_000_000;
        let window = WEEK_SECONDS;
        assert!(!reset_transition_is_boundary(
            Some(now + window - 60),
            Some(87.0),
            now + window + 60,
            Some(86.0),
            Some(now),
            now + 60,
            window,
        ));
        assert!(reset_transition_is_boundary(
            Some(now + 60),
            Some(1.0),
            now + window + 60,
            Some(100.0),
            Some(now),
            now + 60,
            window,
        ));
    }

    #[test]
    fn period_admission_preserves_durable_totals_during_drift_and_clears_on_rollover() {
        let now = 2_000_000_000;
        let two_days = 2 * 86_400;
        let durable_total = super::usage_store::SessionModelTotal {
            cache_write_input_tokens: None,
            model: "SOL".into(),
            total_tokens: 1_000,
            input_tokens: 800,
            cached_input_tokens: 300,
            output_tokens: 200,
        };
        let mut restarted = super::usage_store::SessionCollectionState {
            data_generation: 7,
            reset_at: now - two_days + WEEK_SECONDS,
            window_seconds: WEEK_SECONDS,
            last_quota_observation: Some(super::usage_store::SessionQuotaObservation {
                observed_at: now - two_days,
                remaining_percent: 70.0,
            }),
            model_totals: vec![durable_total.clone()],
            ..super::usage_store::SessionCollectionState::default()
        };
        assert!(!super::admit_session_collection_period(
            &mut restarted,
            now + WEEK_SECONDS,
            WEEK_SECONDS,
            Some(69.0),
            now,
        ));
        assert_eq!(restarted.model_totals, [durable_total.clone()]);

        let mut rollover = super::usage_store::SessionCollectionState {
            data_generation: 8,
            reset_at: now + 30,
            window_seconds: WEEK_SECONDS,
            last_quota_observation: Some(super::usage_store::SessionQuotaObservation {
                observed_at: now - 60,
                remaining_percent: 1.0,
            }),
            model_totals: vec![durable_total],
            ..super::usage_store::SessionCollectionState::default()
        };
        assert!(super::admit_session_collection_period(
            &mut rollover,
            now + WEEK_SECONDS,
            WEEK_SECONDS,
            Some(100.0),
            now,
        ));
        assert!(rollover.model_totals.is_empty());
    }

    #[test]
    fn regression_recovery_replaces_only_cumulative_values_and_preserves_evidence() {
        let reset_at = 1_800_604_800;
        let normal = ModelUsageTotals::from_session_totals(&[
            super::usage_store::SessionModelTotal {
                cache_write_input_tokens: None,
                model: "SOL".into(),
                total_tokens: 100,
                input_tokens: 80,
                cached_input_tokens: 30,
                output_tokens: 20,
            },
            super::usage_store::SessionModelTotal {
                cache_write_input_tokens: None,
                model: "LUNA".into(),
                total_tokens: 50,
                input_tokens: 40,
                cached_input_tokens: 10,
                output_tokens: 10,
            },
        ]);
        let recovered = ModelUsageTotals::from_session_totals(&[
            super::usage_store::SessionModelTotal {
                cache_write_input_tokens: None,
                model: "SOL".into(),
                total_tokens: 1_100,
                input_tokens: 880,
                cached_input_tokens: 330,
                output_tokens: 220,
            },
            super::usage_store::SessionModelTotal {
                cache_write_input_tokens: None,
                model: "LUNA".into(),
                total_tokens: 50,
                input_tokens: 40,
                cached_input_tokens: 10,
                output_tokens: 10,
            },
        ]);
        let checkpoint = super::usage_store::SessionCheckpoint {
            previous_cache_write_input: None,
            root_identity: "11".repeat(32),
            relative_path: "session.jsonl".into(),
            file_device: 1,
            file_inode: 2,
            committed_offset: 100,
            discard_until_lf: false,
            collector_epoch: 3,
            cycle_seq: 4,
            prefix_generation: 5,
            prefix_sha256: "22".repeat(32),
            fully_attributed_from_zero: true,
            token_baseline_known: true,
            last_model: Some("SOL".into()),
            last_task_running: Some(true),
            previous_total: 100,
            previous_input: 80,
            previous_cached_input: 30,
            previous_output: 20,
        };
        let range = super::usage_store::SessionRange {
            root_identity: checkpoint.root_identity.clone(),
            relative_path: checkpoint.relative_path.clone(),
            file_device: checkpoint.file_device,
            file_inode: checkpoint.file_inode,
            start_offset: 50,
            end_offset: 100,
            collector_epoch: 3,
            cycle_seq: 4,
            prefix_generation: 5,
            record_sha256: "33".repeat(32),
        };
        let normal_costs = normal.dollar_totals();
        let normal_tokens = normal.token_totals();
        let mut collection = super::LocalUsageCollection {
            model_usage: normal.clone(),
            history_samples: vec![UsageHistorySample::new_with_usage(
                1_800_000_120,
                reset_at,
                50.0,
                normal_costs,
                normal_tokens,
            )],
            session_checkpoints: vec![checkpoint.clone()],
            session_ranges: vec![range.clone()],
            session_model_totals: normal.to_session_totals(),
            ..super::LocalUsageCollection::default()
        };

        assert!(super::apply_regression_recovery(
            &mut collection,
            recovered.clone()
        ));
        assert_eq!(collection.model_usage, recovered);
        assert_eq!(collection.session_checkpoints, [checkpoint]);
        assert_eq!(collection.session_ranges, [range]);
        let expected_costs = collection.model_usage.dollar_totals();
        let expected_tokens = collection.model_usage.token_totals();
        let sample = &collection.history_samples[0];
        assert!((sample.sol_dollars - expected_costs.sol).abs() < 1e-12);
        assert!((sample.luna_dollars - expected_costs.luna).abs() < 1e-12);
        assert_eq!(sample.sol_tokens, expected_tokens.sol);
        assert_eq!(sample.luna_tokens, expected_tokens.luna);

        let unchanged = collection.clone();
        assert!(!super::apply_regression_recovery(&mut collection, normal));
        assert_eq!(collection.model_usage, unchanged.model_usage);
        assert_eq!(collection.history_samples, unchanged.history_samples);
    }

    #[test]
    fn legacy_component_recovery_requires_checkpointed_sources_and_exact_aggregate() {
        static NEXT_ROOT: AtomicU64 = AtomicU64::new(0);
        let root = std::env::temp_dir().join(format!(
            "codex-info-history-components-{}-{}",
            std::process::id(),
            NEXT_ROOT.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir_all(&root).unwrap();
        let reset_at = 1_800_604_800;
        let boundary_timestamp = 1_800_000_120;
        let timestamp = |value| Utc.timestamp_opt(value, 0).single().unwrap().to_rfc3339();
        let session = |model: &str, at: i64, total: u64, input: u64, cached: u64, output: u64| {
            format!(
                "{}\n{{malformed\n{}\n",
                json!({
                    "timestamp": timestamp(at - 1),
                    "type": "turn_context",
                    "model": model,
                }),
                json!({
                    "timestamp": timestamp(at),
                    "type": "token_count",
                    "payload": {"info": {"total_token_usage": {
                        "total_tokens": total,
                        "input_tokens": input,
                        "cached_input_tokens": cached,
                        "output_tokens": output,
                    }}},
                })
            )
        };
        fs::write(
            root.join("sol.jsonl"),
            session(
                "gpt-5.6-sol",
                1_800_000_060,
                1_000_000,
                800_000,
                300_000,
                200_000,
            ),
        )
        .unwrap();
        fs::write(
            root.join("luna.jsonl"),
            session(
                "gpt-5.6-luna",
                boundary_timestamp,
                2_000_000,
                1_800_000,
                800_000,
                200_000,
            ),
        )
        .unwrap();
        fs::write(
            root.join("post-boundary.jsonl"),
            session(
                "gpt-5.6-terra",
                boundary_timestamp + 60,
                9_000_000,
                9_000_000,
                0,
                0,
            ),
        )
        .unwrap();

        // These models are owned by ordinary checkpointed collection, not
        // the three-column legacy offset, even when present in the prefix.
        for model in ["gpt-6-astra", "future-model"] {
            fs::write(
                root.join(format!("{model}.jsonl")),
                session(model, boundary_timestamp, 100, 80, 20, 20),
            )
            .unwrap();
        }
        let inventory = super::local_input_inventory_for_paths(Some(&root), None).unwrap();
        let checkpoints = inventory
            .selected_session_files
            .iter()
            .filter(|candidate| candidate.recorded_source.relative_path != "post-boundary.jsonl")
            .map(|candidate| super::usage_store::SessionCheckpoint {
                previous_cache_write_input: None,
                root_identity: candidate.recorded_source.root_identity.clone(),
                relative_path: candidate.recorded_source.relative_path.clone(),
                file_device: candidate.recorded_source.file_device,
                file_inode: candidate.recorded_source.file_inode,
                committed_offset: candidate.fingerprint.length,
                discard_until_lf: false,
                collector_epoch: 1,
                cycle_seq: 1,
                prefix_generation: 1,
                prefix_sha256: "00".repeat(32),
                fully_attributed_from_zero: true,
                token_baseline_known: true,
                last_model: None,
                last_task_running: None,
                previous_total: 0,
                previous_input: 0,
                previous_cached_input: 0,
                previous_output: 0,
            })
            .collect::<Vec<_>>();
        let authority = super::usage_store::HistoryContinuityRecovery {
            source_fingerprint: "a".repeat(16),
            source_rows: 2,
            boundary_timestamp,
            reset_at,
            sol_dollars: 8.65,
            terra_dollars: 0.0,
            luna_dollars: 0.456,
            sol_tokens: 1_000_000,
            terra_tokens: 0,
            luna_tokens: 2_000_000,
        };

        assert!(super::recover_checkpointed_history_model_totals(
            &inventory,
            &authority,
            &[],
            WEEK_SECONDS,
        )
        .is_err());
        let mut mismatched = authority.clone();
        mismatched.sol_tokens += 1;
        assert!(super::recover_checkpointed_history_model_totals(
            &inventory,
            &mismatched,
            &checkpoints,
            WEEK_SECONDS,
        )
        .is_err());

        let recovered = super::recover_checkpointed_history_model_totals(
            &inventory,
            &authority,
            &checkpoints,
            WEEK_SECONDS,
        )
        .unwrap();
        let recovered = recovered
            .into_iter()
            .map(|total| (total.model.clone(), total))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(
            recovered,
            vec![
                super::usage_store::SessionModelTotal {
                    cache_write_input_tokens: None,
                    model: "SOL".into(),
                    total_tokens: 1_000_000,
                    input_tokens: 800_000,
                    cached_input_tokens: 300_000,
                    output_tokens: 200_000,
                },
                super::usage_store::SessionModelTotal {
                    cache_write_input_tokens: Some(0),
                    model: "TERRA".into(),
                    total_tokens: 0,
                    input_tokens: 0,
                    cached_input_tokens: 0,
                    output_tokens: 0,
                },
                super::usage_store::SessionModelTotal {
                    cache_write_input_tokens: None,
                    model: "LUNA".into(),
                    total_tokens: 2_000_000,
                    input_tokens: 1_800_000,
                    cached_input_tokens: 800_000,
                    output_tokens: 200_000,
                },
            ]
            .into_iter()
            .map(|total| (total.model.clone(), total))
            .collect::<BTreeMap<_, _>>()
        );

        let partial_path = root.join("post-boundary.jsonl");
        let mut partial = std::fs::OpenOptions::new()
            .append(true)
            .open(&partial_path)
            .unwrap();
        partial.write_all(br#"{"type":"token_count"}"#).unwrap();
        drop(partial);
        let partial_inventory = super::local_input_inventory_for_paths(Some(&root), None).unwrap();
        assert!(super::recover_checkpointed_history_model_totals(
            &partial_inventory,
            &authority,
            &checkpoints,
            WEEK_SECONDS,
        )
        .is_err());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn local_usage_failure_keeps_valid_quota_and_never_invents_zero_history() {
        let mut state = CodexInfoState::preview("normal");
        let reset_at = state.reset_at.expect("preview quota has reset");
        let history_len = state.history.samples.len();
        let previous_cost = state.estimated_cost_label.clone();
        let previous_columns = format_model_usage_columns(&state.model_usage);
        let threads = state.active_threads.clone();

        state.apply_usage_event(usage_event(Some(24.0), reset_at));
        state.apply_thread_result(
            state.auth_epoch,
            ActiveThreadUpdate::Snapshot(threads.clone()),
        );
        state.apply_local_usage_error(state.auth_epoch, reset_at, WEEK_SECONDS);

        assert!(state.has_usage);
        assert_eq!(state.remaining_percent, Some(24.0));
        assert_eq!(state.reset_at, Some(reset_at));
        assert_eq!(state.active_threads, threads);
        assert_eq!(state.estimated_cost_label, previous_cost);
        assert_eq!(
            format_model_usage_columns(&state.model_usage),
            previous_columns
        );
        assert_eq!(state.history.samples.len(), history_len);
        assert!(state.local_usage_error);
        assert_eq!(
            state.status,
            "利用枠は更新しました。履歴は前回値を保持しています。"
        );

        state.model_usage.clear();
        state.estimated_cost_label = "概算 —".into();
        state.history = UsageHistory::default();
        state.reset_at = None;
        let next_reset = reset_at + WEEK_SECONDS;
        state.apply_usage_event(usage_event(Some(24.0), next_reset));
        state.apply_local_usage_error(state.auth_epoch, next_reset, WEEK_SECONDS);
        assert!(state.has_usage);
        assert_eq!(state.remaining_percent, Some(24.0));
        assert!(state.model_usage.is_empty());
        assert_eq!(state.estimated_cost_label, "概算 —");
        assert!(state.history.samples.is_empty());
    }

