    #[test]
    fn recovered_owner_forces_one_immediate_current_read() {
        let mut server =
            ApiServer::start(ApiServerConfig::new("127.0.0.1:0".parse().unwrap()).unwrap())
                .unwrap();
        let mut state = CodexInfoState::preview("normal");
        state.preview = false;
        state.service_current_last_poll = Instant::now();
        state.service_current_force_poll = false;

        super::run_ui_service_timer_cycle_with_owner_check(
            &mut state,
            server.local_addr(),
            false,
            false,
            |_| false,
        );
        let before_recovery = state.service_current_last_poll;
        assert!(state.service_endpoint_error.is_some());
        assert!(state.service_owner_probe_failed);

        super::run_ui_service_timer_cycle_with_owner_check(
            &mut state,
            server.local_addr(),
            false,
            false,
            |_| true,
        );
        assert!(state.service_endpoint_error.is_none());
        assert!(!state.service_owner_probe_failed);
        assert!(state.service_current_last_poll > before_recovery);

        let after_recovery = state.service_current_last_poll;
        super::run_ui_service_timer_cycle_with_owner_check(
            &mut state,
            server.local_addr(),
            false,
            false,
            |_| true,
        );
        assert_eq!(state.service_current_last_poll, after_recovery);
        server.shutdown();
    }

    #[test]
    fn resident_scheduler_requests_one_account_refresh_and_retries_next_interval() {
        let now = Instant::now();
        let mut state = CodexInfoState::preview("normal");
        state.preview = false;
        state.authenticated = false;
        state.checking = false;
        state.last_poll = now - Duration::from_secs(61);
        state.last_thread_poll = now;
        let (command_tx, commands) = std::sync::mpsc::channel();
        let (_event_tx, event_rx) = std::sync::mpsc::channel();
        state.bridge = super::AppServerBridge {
            tx: command_tx,
            rx: event_rx,
        };

        let _ = state.schedule_resident_refresh(now);
        assert!(matches!(
            commands.try_recv(),
            Ok(super::AccountCommand::Read)
        ));
        assert!(state.checking);

        // Later ticks cannot enqueue a second read while the first is active.
        let _ = state.schedule_resident_refresh(now + Duration::from_secs(61));
        assert!(commands.try_recv().is_err());

        // A failed generation keeps last-good state but releases single-flight.
        // The scheduler retries only at the next established interval.
        state.apply_account_error("transient worker failure".into());
        let _ = state.schedule_resident_refresh(now + Duration::from_secs(61));
        assert!(matches!(
            commands.try_recv(),
            Ok(super::AccountCommand::Read)
        ));
        assert!(state.checking);
    }

