    #[test]
    fn resident_service_collects_commits_and_publishes_one_details_generation() {
        let mut state = CodexInfoState::preview("normal");
        state.preview = false;
        let mut publication = super::ResidentPublicationState::default();
        state.history.pending_store_samples = vec![state.history.samples[0].to_store()];
        state.pending_recorder_admission =
            Some((state.auth_epoch, state.current_account_admission().unwrap()));
        assert_eq!(state.public_details().state, PublicState::Initializing);
        let actions = std::cell::RefCell::new(Vec::new());
        let outcome = super::resident_service_cycle(
            &mut state,
            &mut publication,
            |state, pending| {
                assert!(!pending.is_empty());
                actions.borrow_mut().push("write");
                acknowledge_recorder_commit_fixture(state, 1, 0x128, 1);
                Ok(())
            },
            |details| {
                details.validate().unwrap();
                actions.borrow_mut().push("publish");
                Ok(())
            },
        )
        .unwrap();
        assert_eq!(outcome, super::ResidentServiceCycleOutcome::Published);
        assert_eq!(*actions.borrow(), ["write", "publish"]);
        assert!(publication.last_complete.is_some());

        let retained = state.history.samples[0].to_store();
        let retained_marker = super::usage_store::RecordedSessionSource {
            root_identity: "unix:10:20".into(),
            relative_path: "2026/09/session.jsonl".into(),
            file_bytes: 123,
            modified_nanos: 1_700_000_000_000_000_000,
            file_device: 10,
            file_inode: 30,
        };
        let retained_cleanup = super::SessionCleanupPlan {
            sessions_root: PathBuf::from("/tmp/codex-info-retained-cleanup"),
            selected_paths: BTreeSet::new(),
            overflow_files: Vec::new(),
        };
        state.history.pending_store_samples = vec![retained.clone()];
        state.pending_recorded_sessions = vec![retained_marker.clone()];
        state.pending_session_cleanup = vec![retained_cleanup.clone()];
        state.pending_recorder_admission =
            Some((state.auth_epoch, state.current_account_admission().unwrap()));
        let last_complete = publication
            .last_complete
            .clone()
            .expect("ready root was retained");
        let emitted_error = std::cell::RefCell::new(None);
        let result = super::resident_service_cycle(
            &mut state,
            &mut publication,
            |_, _| Err("write rejected".into()),
            |details| {
                details.validate().unwrap();
                *emitted_error.borrow_mut() = Some(details);
                Ok(())
            },
        );
        assert!(matches!(
            result,
            Err(super::ResidentServiceCycleError::Store(_))
        ));
        let mut expected_error = last_complete.clone();
        expected_error.state = PublicState::Error;
        assert_eq!(emitted_error.into_inner(), Some(expected_error));
        assert_eq!(publication.last_complete, Some(last_complete));
        assert!(state.recorder_store_error);
        assert_eq!(state.history.pending_store_samples, [retained]);
        assert_eq!(state.pending_recorded_sessions, [retained_marker]);
        assert_eq!(state.pending_session_cleanup, [retained_cleanup]);

        let recovered = std::cell::RefCell::new(None);
        let outcome = super::resident_service_cycle(
            &mut state,
            &mut publication,
            |state, pending| {
                assert_eq!(pending.samples.len(), 1);
                assert_eq!(pending.recorded_sessions.len(), 1);
                assert_eq!(pending.cleanup_plans.len(), 1);
                acknowledge_recorder_commit_fixture(state, 2, 0x128, 2);
                Ok(())
            },
            |details| {
                details.validate().unwrap();
                *recovered.borrow_mut() = Some(details);
                Ok(())
            },
        )
        .unwrap();
        assert_eq!(outcome, super::ResidentServiceCycleOutcome::Published);
        assert_eq!(
            recovered.into_inner().expect("recovery root").state,
            PublicState::Ready
        );
        assert!(!state.recorder_store_error);
        assert_eq!(
            state
                .acknowledged_recorder_commit
                .as_ref()
                .map(|commit| commit.data_generation),
            Some(2)
        );
        assert!(state.take_pending_recorder_batch().is_empty());

        let mut initial = CodexInfoState::preview("normal");
        initial.preview = false;
        initial.history.pending_store_samples = vec![initial.history.samples[0].to_store()];
        initial.pending_recorder_admission = Some((
            initial.auth_epoch,
            initial.current_account_admission().unwrap(),
        ));
        let mut initial_publication = super::ResidentPublicationState::default();
        let emitted_initial_error = std::cell::RefCell::new(None);
        let result = super::resident_service_cycle(
            &mut initial,
            &mut initial_publication,
            |_, _| Err("initial write rejected".into()),
            |details| {
                details.validate().unwrap();
                *emitted_initial_error.borrow_mut() = Some(details);
                Ok(())
            },
        );
        assert!(matches!(
            result,
            Err(super::ResidentServiceCycleError::Store(_))
        ));
        let initial_error = emitted_initial_error
            .into_inner()
            .expect("initial error root");
        assert_eq!(initial_error.state, PublicState::Error);
        assert_eq!(initial_error.observed_at, None);
        assert!(initial_error.quota.is_none());
        assert!(initial_error.models.is_empty());
        assert_eq!(initial_error.active_thread_count, 0);
        assert!(initial_error.history_periods.is_empty());
        assert!(initial_error.history_samples.is_empty());
        assert!(initial_error.threads.is_empty());
        assert!(initial_publication.last_complete.is_none());
        assert!(initial.recorder_store_error);
        assert_eq!(initial.history.pending_store_samples.len(), 1);
    }

    #[test]
    fn committed_v2_root_keeps_model_tokens_costs_and_history_endpoint_aligned() {
        static NEXT_ROOT: AtomicU64 = AtomicU64::new(0);
        let root = std::env::temp_dir().join(format!(
            "codex-info-v2-root-alignment-{}-{}",
            std::process::id(),
            NEXT_ROOT.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir(&root).unwrap();
        let database = root.join("history.sqlite3");
        let storage_identity = usage_store::StoragePartitionIdentity {
            schema_version: "codex-info-account-db-v1".into(),
            profile_scope_id: "11".repeat(16),
            account_scope_id: "22".repeat(32),
            storage_epoch: 1,
            partition_id: "33".repeat(32),
        };

        let mut state = CodexInfoState::preview("normal");
        state.preview = false;
        state.history = UsageHistory::default();
        state.active_threads.clear();
        state.last_success_at = Some(Utc::now().timestamp());
        state.remaining_percent = Some(61.0);
        state.has_quota_percent = true;
        state.local_usage_pending = true;
        let reset_at = state.reset_at.unwrap();
        let mut totals = ModelUsageTotals::default();
        totals.add(
            "gpt-5.6-sol",
            TokenSnapshot {
                cache_write_input: None,
                total: 2_000_000,
                input: 1_000_000,
                cached_input: 0,
                output: 1_000_000,
            },
        );
        state.pending_session_model_totals = totals.to_session_totals();
        state.pending_collector_generation = Some((0x138, 1));
        state.pending_session_period = Some((reset_at, WEEK_SECONDS));
        state.pending_recorder_admission =
            Some((state.auth_epoch, state.current_account_admission().unwrap()));
        state.apply_local_usage_success(LocalUsageResult {
            auth_epoch: state.auth_epoch,
            reset_at,
            window_seconds: WEEK_SECONDS,
            model_usage: totals,
            model_totals_complete: true,
            history_samples: Vec::new(),
            history_model_totals: Vec::new(),
            recorded_sessions: Vec::new(),
            cleanup_plan: None,
        });

        let admission = state.current_account_admission().unwrap();
        let mut server =
            ApiServer::start(ApiServerConfig::new("127.0.0.1:0".parse().unwrap()).unwrap())
                .unwrap();
        let publisher = server.publisher();
        let mut publication = super::ResidentPublicationState::default();
        let outcome = super::resident_service_cycle_with_recorder_attempt_v2(
            &mut state,
            &mut publication,
            true,
            |state, pending| {
                let mut store = UsageStore::create_partitioned(&database, &storage_identity)
                    .map_err(|error| error.to_string())?;
                let result = store
                    .commit_session_collection_with_observations(
                        usage_store::SessionCollectionCommit {
                            reset_at: pending.reset_at.unwrap(),
                            window_seconds: pending.window_seconds.unwrap(),
                            collector_epoch: pending.collector_epoch.unwrap(),
                            cycle_seq: pending.cycle_seq.unwrap(),
                            samples: &pending.samples,
                            checkpoints: &pending.session_checkpoints,
                            ranges: &pending.session_ranges,
                            model_totals: &pending.session_model_totals,
                            recorded_sessions: &pending.recorded_sessions,
                        },
                        &pending.observations,
                    )
                    .map_err(|error| error.to_string())?;
                let persisted = store
                    .load_recent_observations(Utc::now())
                    .map_err(|error| error.to_string())?;
                assert_eq!(persisted.len(), 1);
                assert_eq!(
                    persisted[0].model_source,
                    usage_store::ModelSource::Confirmed
                );
                assert_eq!(persisted[0].sol_tokens, Some(2_000_000));
                assert_eq!(persisted[0].sol_dollars, Some(35.0));

                let canonical_samples = result.canonical_samples;
                let canonical_observations = result.canonical_observations;
                state.acknowledge_recorder_commit(
                    &admission,
                    daemon::RecorderCommitAck {
                        data_generation: result.data_generation,
                        collector_epoch: 0x138,
                        cycle_seq: 1,
                        last_commit_unix: Utc::now().timestamp(),
                        canonical_samples: canonical_samples.clone(),
                        canonical_observations: canonical_observations.clone(),
                        fallback_model_totals: None,
                        legacy_history_bridged: false,
                    },
                );
                assert!(state
                    .history
                    .apply_committed_samples(canonical_samples, Utc::now()));
                assert!(state
                    .history
                    .apply_committed_observations(canonical_observations, Utc::now()));
                Ok(())
            },
            |v1, v2| publisher.publish_details_v2(v1, v2),
        )
        .unwrap();
        assert_eq!(outcome, super::ResidentServiceCycleOutcome::Published);

        let (pair, wire) = super::fetch_service_details_v2(server.local_addr()).unwrap();
        assert_eq!(wire.models.len(), 1);
        let model = &wire.models[0];
        assert_eq!(model.name, "SOL");
        assert_eq!(model.input_tokens, 1_000_000);
        assert_eq!(model.cached_input_tokens, 0);
        assert_eq!(model.output_tokens, 1_000_000);
        assert_eq!(model.input_dollars, 5.0);
        assert_eq!(model.cached_input_dollars, 0.0);
        assert_eq!(model.output_dollars, 30.0);
        assert_eq!(wire.estimated_cost_label, "概算 $35");
        let current_reset = wire
            .history_periods
            .iter()
            .find(|period| period.current)
            .map(|period| period.reset_at)
            .unwrap();
        let endpoint = wire
            .history_samples
            .iter()
            .filter(|sample| sample.reset_at == current_reset)
            .max_by_key(|sample| sample.timestamp)
            .unwrap();
        assert_eq!(endpoint.model_source, "confirmed");
        assert_eq!(endpoint.sol_tokens, Some(2_000_000));
        assert_eq!(endpoint.sol_dollars, Some(35.0));

        let mut linux_ui = CodexInfoState::service_client();
        assert!(linux_ui.apply_service_details_v2(pair, wire).unwrap());
        assert_eq!(linux_ui.model_usage.len(), 1);
        assert_eq!(linux_ui.model_usage[0].tokens, 2_000_000);
        assert_eq!(linux_ui.estimated_cost_label, "概算 $35");
        assert_eq!(
            linux_ui
                .history
                .samples
                .iter()
                .max_by_key(|sample| sample.timestamp)
                .map(|sample| (sample.sol_tokens, sample.sol_dollars)),
            Some((2_000_000, 35.0))
        );

        server.shutdown();
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn resident_recorder_retries_after_interval_without_dropping_pending_batch() {
        let mut state = CodexInfoState::preview("normal");
        state.preview = false;
        state.history.pending_store_samples = vec![state.history.samples[0].to_store()];
        state.pending_recorder_admission =
            Some((state.auth_epoch, state.current_account_admission().unwrap()));
        let mut publication = super::ResidentPublicationState::default();
        let attempts = std::cell::Cell::new(0_u8);

        let first = super::resident_service_cycle_with_recorder_attempt(
            &mut state,
            &mut publication,
            true,
            |_, _| {
                attempts.set(attempts.get() + 1);
                Err("transient store failure".into())
            },
            |details| {
                details.validate().unwrap();
                Ok(())
            },
        );
        assert!(matches!(
            first,
            Err(super::ResidentServiceCycleError::Store(_))
        ));
        assert_eq!(attempts.get(), 1);
        assert!(state.recorder_store_error);
        assert!(state.has_pending_recorder_batch());

        let now = Instant::now();
        let retry_at = now + daemon::daemon_interval_from_environment();
        assert!(!super::recorder_attempt_due(now, Some(retry_at)));
        let skipped = super::resident_service_cycle_with_recorder_attempt(
            &mut state,
            &mut publication,
            false,
            |_, _| panic!("store retry must be interval-gated"),
            |_| panic!("an interval-gated retry must not republish an identical root"),
        )
        .unwrap();
        assert_eq!(skipped, super::ResidentServiceCycleOutcome::Unchanged);
        assert_eq!(attempts.get(), 1);
        assert!(state.has_pending_recorder_batch());

        assert!(super::recorder_attempt_due(retry_at, Some(retry_at)));
        let recovered = super::resident_service_cycle_with_recorder_attempt(
            &mut state,
            &mut publication,
            true,
            |state, pending| {
                attempts.set(attempts.get() + 1);
                assert!(!pending.is_empty());
                acknowledge_recorder_commit_fixture(state, 2, 0x128, 2);
                Ok(())
            },
            |details| {
                details.validate().unwrap();
                Ok(())
            },
        )
        .unwrap();
        assert_eq!(recovered, super::ResidentServiceCycleOutcome::Published);
        assert_eq!(attempts.get(), 2);
        assert!(!state.recorder_store_error);
        assert!(!state.has_pending_recorder_batch());
    }

    #[test]
    fn stale_recorder_batch_cannot_be_relabelled_after_an_auth_boundary() {
        let mut state = CodexInfoState::preview("normal");
        state.history.pending_store_samples = vec![state.history.samples[0].to_store()];
        state.pending_recorder_admission =
            Some((state.auth_epoch, state.current_account_admission().unwrap()));
        let stale = state.take_pending_recorder_batch();
        assert!(!stale.is_empty());
        state.restore_pending_recorder_batch(stale.clone());

        let old_epoch = state.auth_epoch;
        state.authenticated = false;
        state.apply_account_error("worker boundary".into());
        assert_eq!(state.auth_epoch, old_epoch + 1);
        assert!(state.take_pending_recorder_batch().is_empty());

        state.restore_pending_recorder_batch(stale);
        assert!(state.take_pending_recorder_batch().is_empty());
    }

