    #[test]
    fn history_canonicalizes_a_dominant_minute_without_discarding_the_previous_period() {
        let mut history = UsageHistory::default();
        let previous_reset_at = 1_700_100_000;
        let next_reset_at = 1_700_200_000;
        history.record(UsageHistorySample::new(
            1_700_000_001,
            previous_reset_at,
            75.0,
            ModelDollarTotals {
                sol: 1.0,
                terra: 2.0,
                luna: 3.0,
            },
        ));
        history.record(UsageHistorySample::new(
            1_700_000_039,
            previous_reset_at,
            75.0,
            ModelDollarTotals {
                sol: 4.0,
                terra: 5.0,
                luna: 6.0,
            },
        ));
        assert_eq!(history.samples.len(), 2);
        let previous = history.samples_for_reset(Some(previous_reset_at));
        assert_eq!(previous.len(), 1);
        assert_eq!(previous[0].remaining_percent, 75.0);
        assert_eq!(previous[0].sol_dollars, 4.0);

        history.record(UsageHistorySample::new(
            1_700_000_120,
            next_reset_at,
            70.0,
            ModelDollarTotals::default(),
        ));
        assert_eq!(history.samples.len(), 3);
        assert!(history
            .samples
            .iter()
            .any(|sample| sample.reset_at == previous_reset_at));
        assert!(history
            .samples
            .iter()
            .any(|sample| sample.reset_at == next_reset_at));
        assert_eq!(history.samples_for_reset(Some(previous_reset_at)).len(), 1);
        assert_eq!(history.samples_for_reset(Some(next_reset_at)).len(), 1);
    }

    #[test]
    fn reset_at_jitter_keeps_raw_aliases_and_canonicalizes_one_dominant_row() {
        let mut history = UsageHistory::default();
        let first = UsageHistorySample::new(
            1_700_000_001,
            1_700_100_000,
            75.0,
            ModelDollarTotals {
                sol: 1.0,
                terra: 2.0,
                luna: 3.0,
            },
        );
        let jittered = UsageHistorySample::new(
            1_700_000_039,
            1_700_100_003,
            75.0,
            ModelDollarTotals {
                sol: 4.0,
                terra: 5.0,
                luna: 6.0,
            },
        );

        history.record(first);
        history.record(jittered);

        assert_eq!(history.samples.len(), 2);
        let canonical = canonicalize_public_history_samples(&history.samples);
        assert_eq!(canonical.len(), 1);
        assert_eq!(canonical[0].reset_at, 1_700_100_003);
        assert_eq!(canonical[0].remaining_percent, 75.0);
        assert_eq!(canonical[0].sol_dollars, 4.0);

        history.samples = vec![
            UsageHistorySample::new(
                1_700_000_000,
                1_700_100_000,
                75.0,
                ModelDollarTotals {
                    sol: 1.0,
                    terra: 2.0,
                    luna: 3.0,
                },
            ),
            UsageHistorySample::new(
                1_700_000_000,
                1_700_100_003,
                75.0,
                ModelDollarTotals {
                    sol: 4.0,
                    terra: 5.0,
                    luna: 6.0,
                },
            ),
        ];
        let displayed = canonicalize_public_history_samples(&history.samples);
        assert_eq!(displayed.len(), 1);
        assert_eq!(displayed[0].reset_at, 1_700_100_003);
        assert_eq!(displayed[0].remaining_percent, 75.0);
        assert_eq!(displayed[0].sol_dollars, 4.0);
    }

    #[test]
    fn session_backfill_keeps_an_observed_remaining_value() {
        let mut history = UsageHistory {
            samples: vec![UsageHistorySample::new(
                60,
                1_000,
                42.0,
                ModelDollarTotals {
                    sol: 1.0,
                    terra: 1.0,
                    luna: 1.0,
                },
            )],
            ..UsageHistory::default()
        };
        let backfill = UsageHistorySample::from_model_history(
            60,
            1_003,
            ModelDollarTotals {
                sol: 9.0,
                terra: 8.0,
                luna: 7.0,
            },
        );

        history.apply_backfill_samples(1_003, vec![backfill]);

        assert_eq!(history.samples.len(), 2);
        let canonical = canonicalize_public_history_samples(&history.samples);
        assert_eq!(canonical.len(), 1);
        assert_eq!(canonical[0].remaining_percent, 42.0);
        assert_eq!(canonical[0].sol_dollars, 9.0);
        assert_eq!(canonical[0].terra_dollars, 8.0);
        assert_eq!(canonical[0].luna_dollars, 7.0);
        assert_eq!(canonical[0].reset_at, 1_003);
    }

