    #[test]
    fn model_graph_does_not_invent_spend_during_an_unobserved_gap() {
        let points = [
            HourlyModelSpend {
                timestamp: 0,
                luna: 1.0,
                ..HourlyModelSpend::default()
            },
            HourlyModelSpend {
                timestamp: 60,
                luna: 1.0,
                ..HourlyModelSpend::default()
            },
            HourlyModelSpend {
                timestamp: 3_600,
                luna: 2.0,
                ..HourlyModelSpend::default()
            },
            HourlyModelSpend {
                timestamp: 3_660,
                luna: 2.0,
                ..HourlyModelSpend::default()
            },
        ];
        let smoothed = smooth_model_spend(&points);
        assert_eq!(smoothed[1].luna, 1.0);
        assert_eq!(smoothed[2].luna, 2.0);
        let (flat, rising, inferred) =
            split_metric_line_paths(&smoothed, 0, 3_660, 2.0, |point| point.luna);
        // Both endpoints are real, but the 60..3600 path is unknown. A
        // dashed bridge communicates the bounded estimate without claiming
        // a sudden recovery-time jump or an observed daytime rate.
        assert!(!flat.contains("M1.64 50.00 L98.36 50.00"));
        assert!(!rising.contains("M98.36 50.00 L98.36 1.00"));
        assert!(inferred.matches('M').count() > 2);

        let equal_endpoints = [
            HourlyModelSpend {
                timestamp: 0,
                luna: 2.0,
                ..HourlyModelSpend::default()
            },
            HourlyModelSpend {
                timestamp: 3_600,
                luna: 2.0,
                ..HourlyModelSpend::default()
            },
        ];
        let (flat, rising, inferred) =
            split_metric_line_paths(&equal_endpoints, 0, 3_600, 2.0, |point| point.luna);
        assert!(
            flat.is_empty(),
            "sparse equal endpoints do not prove the unsampled interval was idle"
        );
        assert!(rising.is_empty());
        assert!(
            !inferred.is_empty(),
            "every sparse connection is inferred, including a flat one"
        );
    }

    #[test]
    fn graph_selection_uses_one_monotonic_series_for_lines_and_current_values() {
        let reset_at = 1_000;
        let sample = |timestamp, dollars, tokens| {
            UsageHistorySample::new_with_usage(
                timestamp,
                reset_at,
                80.0,
                ModelDollarTotals {
                    sol: dollars,
                    ..ModelDollarTotals::default()
                },
                ModelTokenTotals {
                    sol: tokens,
                    ..ModelTokenTotals::default()
                },
            )
        };
        let samples = [
            sample(60, 10.0, 100),
            sample(120, 0.0, 0),
            sample(180, 12.0, 120),
        ];
        let references = samples.iter().collect::<Vec<_>>();

        let dollars = graph_paths_for_selection(&references, 0, 240, false, false, true, false);
        assert_eq!(dollars.current_sol_label, "$12.00");
        assert!(!dollars.sol_rising.contains("M50.00 99.00"));
        assert!(dollars.sol_inferred.matches('M').count() > 2);

        let tokens = graph_paths_for_selection(&references, 0, 240, false, false, true, true);
        assert_eq!(tokens.current_sol_label, "120");
        assert!(!tokens.sol_rising.contains("M50.00 99.00"));
        assert!(tokens.sol_inferred.matches('M').count() > 2);
    }

    #[test]
    fn first_observation_does_not_fabricate_a_diagonal_rise() {
        let points = graph_time_endpoints(
            vec![HourlyModelSpend {
                timestamp: 180,
                sol: 4.0,
                ..HourlyModelSpend::default()
            }],
            0,
            240,
        );
        let (flat, rising, inferred) =
            split_metric_line_paths(&points, 0, 240, 4.0, |point| point.sol);

        assert!(!flat.contains("M0.00 99.00 L75.00 99.00"));
        assert!(flat.contains("M75.00 1.00 L100.00 1.00"));
        assert!(!rising.contains("M75.00 99.00 L75.00 1.00"));
        assert!(!rising.contains("M0.00 99.00 L75.00 1.00"));
        assert!(inferred.is_empty());
    }

    #[test]
    fn unused_intervals_mark_only_confirmed_idle_segments() {
        let points = [
            HourlyModelSpend {
                timestamp: 0,
                ..HourlyModelSpend::default()
            },
            HourlyModelSpend {
                timestamp: 60,
                ..HourlyModelSpend::default()
            },
            HourlyModelSpend {
                timestamp: 120,
                sol: 1.0,
                ..HourlyModelSpend::default()
            },
            HourlyModelSpend {
                timestamp: 180,
                sol: 1.0,
                ..HourlyModelSpend::default()
            },
            HourlyModelSpend {
                timestamp: 240,
                sol: 2.0,
                ..HourlyModelSpend::default()
            },
        ];
        assert_eq!(
            unused_interval_positions(&points, 0, 240),
            vec![
                UnusedIntervalPosition {
                    start: 0.0,
                    width: 25.0,
                    preserve_boundary: false,
                },
                UnusedIntervalPosition {
                    start: 50.0,
                    width: 25.0,
                    preserve_boundary: false,
                },
            ]
        );

        let first_use = [
            HourlyModelSpend {
                timestamp: 0,
                ..HourlyModelSpend::default()
            },
            HourlyModelSpend {
                timestamp: 180,
                sol: 4.0,
                ..HourlyModelSpend::default()
            },
            HourlyModelSpend {
                timestamp: 240,
                sol: 4.0,
                ..HourlyModelSpend::default()
            },
        ];
        assert_eq!(
            unused_interval_positions(&first_use, 0, 240),
            vec![UnusedIntervalPosition {
                start: 75.0,
                width: 25.0,
                preserve_boundary: false,
            }]
        );

        let astra_activity = [
            HourlyModelSpend {
                timestamp: 0,
                astra: 10.0,
                ..HourlyModelSpend::default()
            },
            HourlyModelSpend {
                timestamp: 60,
                astra: 11.0,
                ..HourlyModelSpend::default()
            },
            HourlyModelSpend {
                timestamp: 120,
                astra: 12.0,
                ..HourlyModelSpend::default()
            },
        ];
        assert!(unused_interval_positions(&astra_activity, 0, 120).is_empty());

        let fixed_models_flat = [
            HourlyModelSpend {
                timestamp: 0,
                ..HourlyModelSpend::default()
            },
            HourlyModelSpend {
                timestamp: 60,
                ..HourlyModelSpend::default()
            },
        ];
        let additional_model = BTreeMap::from([(
            "future-model".to_owned(),
            BTreeMap::from([
                (
                    0,
                    super::GraphModelPoint {
                        dollar: 1.0,
                        tokens: 10.0,
                        reliable: true,
                        published: true,
                    },
                ),
                (
                    60,
                    super::GraphModelPoint {
                        dollar: 2.0,
                        tokens: 20.0,
                        reliable: true,
                        published: true,
                    },
                ),
            ]),
        )]);
        assert!(super::unused_interval_positions_with_confirmed_gaps(
            &fixed_models_flat,
            0,
            60,
            &[],
            Some((&additional_model, false)),
        )
        .is_empty());
    }

