    #[test]
    fn unused_intervals_use_tokens_in_both_display_metrics() {
        let samples = [
            UsageHistorySample::new_with_usage(
                0,
                1_000,
                100.0,
                ModelDollarTotals::default(),
                ModelTokenTotals::default(),
            ),
            UsageHistorySample::new_with_usage(
                60,
                1_000,
                100.0,
                ModelDollarTotals {
                    sol: 1.0,
                    ..ModelDollarTotals::default()
                },
                ModelTokenTotals {
                    sol: 100,
                    ..ModelTokenTotals::default()
                },
            ),
            UsageHistorySample::new_with_usage(
                120,
                1_000,
                100.0,
                ModelDollarTotals {
                    sol: 1.0,
                    ..ModelDollarTotals::default()
                },
                ModelTokenTotals {
                    sol: 200,
                    ..ModelTokenTotals::default()
                },
            ),
            UsageHistorySample::new_with_usage(
                180,
                1_000,
                100.0,
                ModelDollarTotals {
                    sol: 1.0,
                    ..ModelDollarTotals::default()
                },
                ModelTokenTotals {
                    sol: 200,
                    ..ModelTokenTotals::default()
                },
            ),
            UsageHistorySample::new_with_usage(
                240,
                1_000,
                100.0,
                ModelDollarTotals {
                    sol: 1.0,
                    ..ModelDollarTotals::default()
                },
                ModelTokenTotals {
                    sol: 200,
                    ..ModelTokenTotals::default()
                },
            ),
        ];
        let references = samples.iter().collect::<Vec<_>>();
        let without_models =
            graph_paths_for_selection(&references, 0, 240, true, true, true, false);
        assert!(without_models.unused_intervals.is_empty());
        let timelines: super::GraphModelTimelines = [
            (
                "SOL".to_owned(),
                samples
                    .iter()
                    .map(|sample| {
                        (
                            sample.timestamp,
                            super::GraphModelPoint {
                                dollar: sample.sol_dollars,
                                tokens: sample.sol_tokens as f64,
                                reliable: true,
                                published: true,
                            },
                        )
                    })
                    .collect(),
            ),
            (
                "LUNA".to_owned(),
                samples
                    .iter()
                    .map(|sample| {
                        (
                            sample.timestamp,
                            super::GraphModelPoint {
                                dollar: 0.0,
                                tokens: 0.0,
                                reliable: true,
                                published: true,
                            },
                        )
                    })
                    .collect(),
            ),
            (
                "TERRA".to_owned(),
                samples
                    .iter()
                    .map(|sample| {
                        (
                            sample.timestamp,
                            super::GraphModelPoint {
                                dollar: 0.0,
                                tokens: 0.0,
                                reliable: true,
                                published: true,
                            },
                        )
                    })
                    .collect(),
            ),
        ]
        .into_iter()
        .collect();
        let graph = |tokens| {
            super::graph_paths_for_selection_with_sources_and_astra(
                &references,
                0,
                240,
                true,
                true,
                true,
                false,
                tokens,
                &Default::default(),
                &[],
                &timelines,
            )
        };
        let dollars = graph(false);
        let tokens = graph(true);

        assert_eq!(dollars.unused_intervals.len(), 1);
        assert!((dollars.unused_intervals[0].start - 50.0).abs() < 0.000_001);
        assert!((dollars.unused_intervals[0].width - 50.0).abs() < 0.000_001);
        assert_eq!(tokens.unused_intervals.len(), 1);
        assert!((tokens.unused_intervals[0].start - 50.0).abs() < 0.000_001);
        assert!((tokens.unused_intervals[0].width - 50.0).abs() < 0.000_001);
    }

